class CodexManager {
  #storage;
  #bus;
  #data;

  constructor({ bus = null, storage = globalThis.localStorage } = {}) {
    this.#bus = bus;
    this.#storage = storage;
    this.#data = this.#load();
  }

  setBus(bus) {
    this.#bus = bus;
  }

  #getDefaultData() {
    return {
      memorial: [],
      career: {
        totalDaysSurvived: 0,
        totalExpeditions: 0,
        totalKmTraveled: 0,
        totalSectorsVisited: 0,
        totalEnemiesDefeated: 0,
        totalEnemiesSpared: 0,
        totalBarterValue: 0,
        totalVehiclesRestored: 0,
        totalCraftsDone: 0,
        totalFuelSiphoned: 0,
        totalScavenges: 0,
        totalMedicalTreatments: 0,
      },
      achievements: {},
      unlockedCodex: ['iron_guard', 'nomad_guild', 'trauma_tccc', 'weather_extremes'],
    };
  }

  #load() {
    try {
      const raw = this.#storage?.getItem(STORAGE_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        return {
          ...this.#getDefaultData(),
          ...parsed,
          career: { ...this.#getDefaultData().career, ...(parsed.career || {}) },
          achievements: { ...(parsed.achievements || {}) },
          unlockedCodex: Array.isArray(parsed.unlockedCodex) ? parsed.unlockedCodex : this.#getDefaultData().unlockedCodex,
          memorial: Array.isArray(parsed.memorial) ? parsed.memorial : [],
        };
      }
    } catch (e) {
      console.warn('[codex] failed to load codex storage', e);
    }
    return this.#getDefaultData();
  }

  #save() {
    try {
      this.#storage?.setItem(STORAGE_KEY, JSON.stringify(this.#data));
    } catch (e) {
      console.warn('[codex] failed to write codex storage', e);
    }
  }

  get memorial() {
    return this.#data.memorial;
  }

  get career() {
    return this.#data.career;
  }

  get achievements() {
    return this.#data.achievements;
  }

  get unlockedCodex() {
    return this.#data.unlockedCodex;
  }

  /**
   * Records a fallen survivor to the permanent memorial log upon death.
   */
  recordFallenSurvivor(state) {
    if (!state?.player) return null;

    const days = Math.max(0.1, Math.round(((state.player.diedAt ?? state.time?.minutes ?? 0) / 1440) * 10) / 10);
    const visitedNodes = Object.values(state.world?.nodes || {}).filter((n) => n.visited).length;

    const record = {
      id: `memorial_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
      name: state.player.name || 'Bilinmeyen Hayatta Kalan',
      age: state.player.age || 28,
      archetype: state.player.archetype || 'scavenger',
      bloodType: state.player.bloodType || 'A+',
      trait: state.player.trait || 'stoic',
      startingLocation: 'istanbul',
      deathLocation: state.world?.currentNodeId || 'istanbul',
      causeOfDeath: state.player.causeOfDeath || 'wounds',
      diedAtTimestamp: Date.now(),
      daysSurvived: days,
      sectorsVisited: visitedNodes,
      enemiesNeutralized: state.combat?.totalEnemiesDefeated || 0,
      barterVolume: state.economy?.totalBarterVolume || 0,
      kmTraveled: state.world?.totalKmTraveled || 0,
      vehiclesRestored: state.vehicles?.fleet ? Object.values(state.vehicles.fleet).filter((v) => v.restored).length : 0,
      epitaph: this.#generateEpitaph(state.player.name, state.player.causeOfDeath, state.world?.currentNodeId),
    };

    // Update cumulative career statistics
    this.#data.career.totalExpeditions += 1;
    this.#data.career.totalDaysSurvived = Math.round((this.#data.career.totalDaysSurvived + days) * 10) / 10;
    this.#data.career.totalSectorsVisited += visitedNodes;

    // Check endurance milestone
    if (days >= 10) {
      this.unlockAchievement('endurance_champion');
    }

    // Prepend to memorial (latest death at top, capped at 40 records)
    this.#data.memorial.unshift(record);
    if (this.#data.memorial.length > 40) {
      this.#data.memorial.pop();
    }

    this.#save();
    return record;
  }

  #generateEpitaph(name, cause, location) {
    const epitaphs = {
      blood_loss: `${name}, ${location} harabelerinde kan kaybı ve şok içinde son nefesini verdi.`,
      hypothermia: `${name}, dondurucu kıyamet kışında soğuğa yenik düştü.`,
      radiation: `${name}, ölümcül radyoaktif kül fırtınasının ortasında yığıldı.`,
      starvation: `${name}, açlık ve bitkinlik içinde harabelerde sessizliğe gömüldü.`,
      dehydration: `${name}, kavurucu susuzluk içinde bir damla suya hasret kalarak can verdi.`,
      acid_burns: `${name}, zehirli asit yağmurunda kimyasal yanıklarla can verdi.`,
      wounds: `${name}, çatışma yaralarına yenik düşerek toprağa karıştı.`,
    };
    return epitaphs[cause] || `${name}, Avrasya harabelerinde hayata gözlerini yumdu.`;
  }

  /**
   * Tracks incremental career statistics across active gameplay.
   */
  trackCareer(statName, delta = 1) {
    if (this.#data.career[statName] !== undefined) {
      this.#data.career[statName] = Math.round((this.#data.career[statName] + delta) * 10) / 10;
      this.#save();
    }
  }

  /**
   * Evaluates and unlocks an achievement permanently.
   */
  unlockAchievement(achId) {
    if (!ACHIEVEMENTS_CATALOG[achId]) return false;
    if (this.#data.achievements[achId]) return false; // Already unlocked

    this.#data.achievements[achId] = {
      unlockedAt: Date.now(),
    };
    this.#save();

    // Trigger audio & broadcast notification event
    audioEngine.playAchievementChime();
    if (this.#bus) {
      this.#bus.emit('codex:achievement_unlocked', {
        id: achId,
        catalog: ACHIEVEMENTS_CATALOG[achId],
      });
    }

    return true;
  }

  /**
   * Unlocks a classified field codex entry.
   */
  unlockCodexEntry(entryId) {
    if (!LORE_CODEX_CATALOG[entryId]) return false;
    if (this.#data.unlockedCodex.includes(entryId)) return false;

    this.#data.unlockedCodex.push(entryId);
    this.#save();
    return true;
  }

  /**
   * Calculates overall survivor reputation rank based on career metrics.
   */
  getSurvivalRank() {
    const days = this.#data.career.totalDaysSurvived;
    const achCount = Object.keys(this.#data.achievements).length;

    if (days >= 50 || achCount >= 10) {
      return { tier: 5, rankKey: 'codex.rank.tier_5', glyph: '👑' };
    }
    if (days >= 25 || achCount >= 7) {
      return { tier: 4, rankKey: 'codex.rank.tier_4', glyph: '🎖️' };
    }
    if (days >= 10 || achCount >= 4) {
      return { tier: 3, rankKey: 'codex.rank.tier_3', glyph: '⚔️' };
    }
    if (days >= 3 || achCount >= 1) {
      return { tier: 2, rankKey: 'codex.rank.tier_2', glyph: '🐺' };
    }
    return { tier: 1, rankKey: 'codex.rank.tier_1', glyph: '🏕️' };
  }

  /**
   * Resets all memorial and career records (wiping history).
   */
  clearAll() {
    this.#data = this.#getDefaultData();
    this.#save();
  }
}

const codexManager = new CodexManager();



  // --- src/modules/status/bodyStatus.js ---
/**
 * Last Breath // Targeted Body Trauma & Anatomical Status Engine
 * Zero-dependency Vanilla JS module replacing flat hit points
 * with realistic multi-part trauma, arterial hemodynamics, and targeted treatments.
 */

const BODY_PARTS = ['head', 'torso', 'leftArm', 'rightArm', 'leftLeg', 'rightLeg'];

const BLEED_LEVELS = {
  NONE: 'none',
  MINOR: 'minor',
  ARTERIAL: 'arterial',
};

// EventBus event channel names
const EVENT_BODY_UPDATED = 'body:updated';
const EVENT_BLEEDING_ALERT = 'body:bleeding_alert';
const EVENT_FRACTURE_ALERT = 'body:fracture_alert';
const EVENT_PNEUMOTHORAX_ALERT = 'body:pneumothorax_alert';
const EVENT_INFECTION_ALERT = 'body:infection_alert';

// Hourly blood loss rates in absolute HP
const BLEED_RATES_PER_HOUR = {
  none: 0,
  minor: 1.5,
  arterial: 14.0, // High-speed pulsatile loss leading to rapid shock
};

// Anatomical hit probability distribution when target part is unspecified
const DEFAULT_HIT_WEIGHTS = {
  torso: 0.38,
  leftLeg: 0.16,
  rightLeg: 0.16,
  leftArm: 0.12,
  rightArm: 0.12,
  head: 0.06,
};

// Weight of each part in computing overall body integrity (0..100)
const VITAL_PART_WEIGHTS = {
  head: 0.25,
  torso: 0.35,
  leftArm: 0.10,
  rightArm: 0.10,
  leftLeg: 0.10,
  rightLeg: 0.10,
};

/**
 * Creates default state for a single anatomical part.
 */
function createDefaultBodyPart() {
  return {
    health: 100,
    bleeding: BLEED_LEVELS.NONE,
    fractures: false,
    burns: false,
    infectionRisk: 0, // 0 to 100
    punctured: false, // Tension pneumothorax flag for torso / deep puncture
  };
}

/**
 * Creates default complete body trauma state.
 */
function createDefaultBodyState() {
  return {
    head: createDefaultBodyPart(),
    torso: createDefaultBodyPart(),
    leftArm: createDefaultBodyPart(),
    rightArm: createDefaultBodyPart(),
    leftLeg: createDefaultBodyPart(),
    rightLeg: createDefaultBodyPart(),
  };
}

/**
 * Checks if a body part is a limb (compatible with windlass tourniquets and splints).
 */
function isLimb(partName) {
  return ['leftArm', 'rightArm', 'leftLeg', 'rightLeg'].includes(partName);
}

/**
 * Applies targeted physical trauma to a specific or weighted body part.
 * Emits specific EventBus alerts when arterial bleeds, fractures, or pneumothorax occur.
 */
function applyBodyDamage(bodyState, {
  part = null,
  amount = 10,
  damageType = 'blunt', // 'blunt', 'ballistic', 'slashing', 'puncture', 'burn', 'blast'
  puncture = false,
  fractureChance = 0,
  arterialChance = 0,
  rng = null,
  bus = null,
} = {}) {
  const current = bodyState || createDefaultBodyState();

  // Select target part
  let targetPart = part;
  if (!targetPart || !BODY_PARTS.includes(targetPart)) {
    if (rng && typeof rng.weighted === 'function') {
      const pool = Object.entries(DEFAULT_HIT_WEIGHTS).map(([k, w]) => ({ part: k, weight: w }));
      targetPart = rng.weighted(pool, (entry) => entry.weight).part;
    } else {
      targetPart = 'torso';
    }
  }

  const p = current[targetPart] || (current[targetPart] = createDefaultBodyPart());
  const beforeHealth = p.health;
  p.health = Math.max(0, Math.min(100, p.health - amount));

  const alerts = [];

  // Ballistic, slashing, or puncture wounds trigger bleeding
  const isPenetrating = ['ballistic', 'slashing', 'puncture', 'blast'].includes(damageType);
  if (isPenetrating && amount > 4) {
    const defaultArterial = damageType === 'ballistic' ? 0.25 : (damageType === 'puncture' ? 0.20 : 0.12);
    const calcArterialChance = arterialChance || defaultArterial;
    const isArterial = rng ? rng.chance(calcArterialChance) : (Math.random() < calcArterialChance);

    if (isArterial && p.bleeding !== BLEED_LEVELS.ARTERIAL) {
      p.bleeding = BLEED_LEVELS.ARTERIAL;
      alerts.push({ type: EVENT_BLEEDING_ALERT, part: targetPart, level: BLEED_LEVELS.ARTERIAL });
      if (bus) bus.emit(EVENT_BLEEDING_ALERT, { part: targetPart, level: BLEED_LEVELS.ARTERIAL });
    } else if (p.bleeding === BLEED_LEVELS.NONE) {
      p.bleeding = BLEED_LEVELS.MINOR;
      alerts.push({ type: EVENT_BLEEDING_ALERT, part: targetPart, level: BLEED_LEVELS.MINOR });
      if (bus) bus.emit(EVENT_BLEEDING_ALERT, { part: targetPart, level: BLEED_LEVELS.MINOR });
    }

    // Dirt/particulate in wound raises infection risk
    p.infectionRisk = Math.min(100, p.infectionRisk + Math.round(amount * 0.6));
  }

  // Torso tension pneumothorax risk
  if (targetPart === 'torso' && (puncture || damageType === 'puncture' || (damageType === 'ballistic' && amount >= 18))) {
    if (!p.punctured) {
      p.punctured = true;
      alerts.push({ type: EVENT_PNEUMOTHORAX_ALERT, part: 'torso' });
      if (bus) bus.emit(EVENT_PNEUMOTHORAX_ALERT, { part: 'torso' });
    }
  }

  // Fracture check on limbs/head
  const isBluntOrBlast = ['blunt', 'blast'].includes(damageType);
  const calcFractureChance = fractureChance || (isBluntOrBlast && amount >= 15 ? 0.45 : (amount >= 28 ? 0.35 : 0));
  if (!p.fractures && calcFractureChance > 0) {
    const fractured = rng ? rng.chance(calcFractureChance) : (Math.random() < calcFractureChance);
    if (fractured) {
      p.fractures = true;
      alerts.push({ type: EVENT_FRACTURE_ALERT, part: targetPart });
      if (bus) bus.emit(EVENT_FRACTURE_ALERT, { part: targetPart });
    }
  }

  // Thermal burns
  if (damageType === 'burn') {
    p.burns = true;
    p.infectionRisk = Math.min(100, p.infectionRisk + 30);
  }

  if (bus) {
    bus.emit(EVENT_BODY_UPDATED, { part: targetPart, bodyState: current, alerts });
  }

  return {
    targetPart,
    damageDealt: beforeHealth - p.health,
    partState: { ...p },
    alerts,
  };
}

/**
 * Resolves medical item application to a specific body part.
 * Returns { success: boolean, reasonKey: string, effectDesc: string }
 */
function applyMedicalTreatment(bodyState, itemId = '', targetPart = 'torso', { bus = null } = {}) {
  if (!bodyState || !bodyState[targetPart]) {
    return { success: false, reasonKey: 'invalid_part' };
  }
  if (!itemId || typeof itemId !== 'string') {
    return { success: false, reasonKey: 'invalid_item' };
  }

  const part = bodyState[targetPart];
  let treated = false;
  let actionDesc = '';

  // 1. Tourniquets (CAT / SOFFT-T)
  if (itemId === 'combat_tourniquet_cat' || itemId === 'softt_wide_tourniquet' || itemId.includes('tourniquet')) {
    if (!isLimb(targetPart)) {
      return { success: false, reasonKey: 'tourniquet_requires_limb' };
    }
    if (part.bleeding === BLEED_LEVELS.NONE) {
      return { success: false, reasonKey: 'no_active_bleed' };
    }
    const wasArterial = part.bleeding === BLEED_LEVELS.ARTERIAL;
    part.bleeding = BLEED_LEVELS.NONE;
    treated = true;
    actionDesc = wasArterial
      ? 'Turnike sıkıldı: Şiddetli atardamar kanaması derhal durduruldu.'
      : 'Turnike uygulandı: Uzuvdaki kanama tamamen kesildi.';
  }

  // 2. Hemostatic Combat Gauze / QuikClot / Israeli Pressure Dressings
  else if (
    itemId === 'quikclot_hemostatic_gauze' ||
    itemId === 'hemostatic_gauze_z_fold' ||
    itemId === 'emergency_israeli_bandage' ||
    itemId === 'pressure_dressing_trauma_4in'
  ) {
    if (part.bleeding === BLEED_LEVELS.NONE && part.health >= 100) {
      return { success: false, reasonKey: 'no_bleeding_wound' };
    }
    if (part.bleeding === BLEED_LEVELS.ARTERIAL) {
      part.bleeding = BLEED_LEVELS.MINOR; // Demotes arterial to manageable minor bleed
      actionDesc = 'Hemostatik kaolin sargı yaraya tamponlandı: Atardamar fışkırması durduruldu, kanama hafifledi.';
    } else {
      part.bleeding = BLEED_LEVELS.NONE;
      actionDesc = 'Basınçlı travma sargısı sarıldı: Kanama başarıyla durduruldu.';
    }
    part.health = Math.min(100, part.health + 12);
    part.infectionRisk = Math.max(0, part.infectionRisk - 25);
    treated = true;
  }

  // 3. Vented Chest Seals / Decompression Needles / Nasopharyngeal Airway (Pneumothorax / Torso Puncture)
  else if (
    itemId === 'chest_seal_vented' ||
    itemId === 'chest_seal_twin_pack' ||
    itemId === 'decompression_needle_14g' ||
    itemId === 'nasopharyngeal_airway_28fr'
  ) {
    if (targetPart !== 'torso') {
      return { success: false, reasonKey: 'chest_seal_requires_torso' };
    }
    if (!part.punctured && part.bleeding === BLEED_LEVELS.NONE && part.health >= 100) {
      return { success: false, reasonKey: 'no_chest_puncture' };
    }
    part.punctured = false;
    if (part.bleeding === BLEED_LEVELS.MINOR) part.bleeding = BLEED_LEVELS.NONE;
    part.health = Math.min(100, part.health + 18);
    treated = true;
    actionDesc = itemId.includes('needle')
      ? '14G dekompresyon iğnesiyle 2. kaburgalar arası boşluk delindi: Plevral hava boşaltıldı, akciğer rahatlatıldı.'
      : (itemId.includes('airway')
        ? 'Nazofaringeal hava yolu yerleştirildi: Solunum kanalı açıldı ve nefes alış normale döndü.'
        : 'Valfli hidrojel göğüs mührü yapıştırıldı: Açık göğüs yarası kapatıldı, pnömotoraks önlendi.');
  }

  // 4. SAM Splints & Orthopedic Supports (Fractures / Joint sprains)
  else if (
    itemId === 'sam_splint_roll' ||
    itemId === 'sam_splint_36inch' ||
    itemId === 'triangular_bandage_sling' ||
    itemId === 'cervical_extrication_collar' ||
    itemId === 'cohesive_flexible_vet_wrap'
  ) {
    const isCollar = itemId.includes('collar');
    if (!isCollar && !isLimb(targetPart)) {
      return { success: false, reasonKey: 'splint_requires_limb' };
    }
    if (!part.fractures && part.health >= 100) {
      return { success: false, reasonKey: 'no_fracture' };
    }
    const hadFracture = part.fractures;
    part.fractures = false;
    part.health = Math.min(100, part.health + 15);
    treated = true;
    actionDesc = hadFracture
      ? 'Alüminyum SAM ateli şekillendirilip sabitlendi: Kırık kemik hareketsizleştirildi, uzuv stabilize edildi.'
      : 'Ortopedik askı/bandaj uygulandı: Eklem burkulması ve doku gerginliği giderildi.';
  }

  // 5. Burn Treatments (Hydrogel Dressings, Burn Sheets, Burn Creams)
  else if (
    itemId === 'burn_hydrogel_dressing' ||
    itemId === 'burn_sheet_sterile' ||
    itemId === 'silver_sulfadiazine_burn_cream' ||
    itemId === 'burn_gel_hydrogel_packet' ||
    itemId === 'calamine_lotion_bottle' ||
    itemId === 'hydrocortisone_cream_1pct' ||
    itemId === 'zinc_oxide_petroleum_paste'
  ) {
    if (!part.burns && part.health >= 100 && part.infectionRisk <= 0) {
      return { success: false, reasonKey: 'no_burns' };
    }
    part.burns = false;
    part.infectionRisk = Math.max(0, part.infectionRisk - 40);
    part.health = Math.min(100, part.health + 20);
    treated = true;
    actionDesc = 'Steril hidrojel yanık örtüsü ve gümüş sülfadiazin merhemi uygulandı: Termal yanık soğutuldu ve doku yenilendi.';
  }

  // 6. Antiseptics & Wound Irrigation (Infection Risk Decontamination)
  else if (
    itemId === 'antiseptic' ||
    itemId === 'povidone_iodine_bottle' ||
    itemId === 'rubbing_alcohol_bottle' ||
    itemId === 'hydrogen_peroxide_bottle' ||
    itemId === 'chlorhexidine_scrub' ||
    itemId === 'chlorhexidine_gluconate_4pct' ||
    itemId === 'alcohol_prep_swabs' ||
    itemId === 'potassium_permanganate_crystals' ||
    itemId === 'antibacterial_triple_ointment' ||
    itemId === 'eye_wash_sterile_saline_bottle'
  ) {
    part.infectionRisk = Math.max(0, part.infectionRisk - 60);
    for (const p of Object.values(bodyState)) {
      p.infectionRisk = Math.max(0, p.infectionRisk - 30);
    }
    part.health = Math.min(100, part.health + 8);
    treated = true;
    actionDesc = 'Antiseptik solüsyonla açık yara yıkandı ve dezenfekte edildi: Bakteriyel enfeksiyon riski temizlendi.';
  }

  // 7. Systemic Broad-Spectrum Antibiotics
  else if (
    itemId === 'ciprofloxacin_antibiotic' ||
    itemId === 'ciprofloxacin_500mg_box' ||
    itemId === 'antibiotics' ||
    itemId === 'amoxicillin_capsules' ||
    itemId === 'amoxicillin_clavulanate_box' ||
    itemId === 'doxycycline_hyclate' ||
    itemId === 'doxycycline_100mg_bottle' ||
    itemId === 'azithromycin_250mg_zpack' ||
    itemId === 'metronidazole_500mg_bottle' ||
    itemId === 'chloroquine_phosphate_tabs'
  ) {
    for (const p of Object.values(bodyState)) {
      p.infectionRisk = 0;
      p.health = Math.min(100, p.health + 6);
    }
    treated = true;
    actionDesc = 'Geniş spektrumlu antibiyotik dozu alındı: Sistemik bakteri üremesi durduruldu ve doku enfeksiyonu sıfırlandı.';
  }

  // 8. Surgical Sutures, Skin Staplers & Liquid Adhesives
  else if (
    itemId === 'suture_needle_silk' ||
    itemId === 'disposable_skin_stapler' ||
    itemId === 'liquid_skin_adhesive' ||
    itemId === 'butterfly_wound_closure'
  ) {
    if (part.bleeding === BLEED_LEVELS.NONE && part.health >= 100) {
      return { success: false, reasonKey: 'no_wounds' };
    }
    if (part.bleeding === BLEED_LEVELS.ARTERIAL) {
      part.bleeding = BLEED_LEVELS.MINOR;
      actionDesc = 'Derin kesik cerrahi zımba/dikişle kapatıldı: Atardamar yaralanması sınırlandırıldı.';
    } else {
      part.bleeding = BLEED_LEVELS.NONE;
      actionDesc = 'Cerrahi dikiş ve doku yapıştırıcısıyla yara kenarları birleştirildi: Kesik tamamen dikildi.';
    }
    part.health = Math.min(100, part.health + 18);
    part.infectionRisk = Math.max(0, part.infectionRisk - 20);
    treated = true;
  }

  // 9. Standard Bandages & Gauze
  else if (itemId === 'bandage' || itemId === 'gauze_roll_sterile' || itemId === 'adhesive_plaster_strip' || itemId === 'elastic_compression_wrap') {
    if (part.bleeding === BLEED_LEVELS.NONE && part.health >= 100) {
      return { success: false, reasonKey: 'no_wounds' };
    }
    if (part.bleeding === BLEED_LEVELS.MINOR) {
      part.bleeding = BLEED_LEVELS.NONE;
      actionDesc = 'Steril sargı bezi yaraya sarıldı: Kanama durduruldu.';
    } else if (part.bleeding === BLEED_LEVELS.ARTERIAL) {
      return { success: false, reasonKey: 'bandage_insufficient_for_arterial' };
    } else {
      actionDesc = 'Temiz pansuman yapıldı: Hasarlı doku koruma altına alındı.';
    }
    part.health = Math.min(100, part.health + 8);
    treated = true;
  }

  // 10. Comprehensive First Aid Kits & Military IFAKs
  else if (itemId === 'first_aid_kit' || itemId === 'military_ifak_complete') {
    for (const p of Object.values(bodyState)) {
      if (p.bleeding === BLEED_LEVELS.ARTERIAL) p.bleeding = BLEED_LEVELS.MINOR;
      else if (p.bleeding === BLEED_LEVELS.MINOR) p.bleeding = BLEED_LEVELS.NONE;
      p.burns = false;
      p.punctured = false;
      p.infectionRisk = Math.max(0, p.infectionRisk - 50);
      p.health = Math.min(100, p.health + 15);
    }
    treated = true;
    actionDesc = 'Askeri travma çantası açıldı: Kapsamlı müdahaleyle kanamalar durduruldu, yaralar dezenfekte edildi.';
  }

  // 11. IV Fluid Resuscitation
  else if (
    itemId === 'iv_saline_bag_500ml' ||
    itemId === 'ringer_lactate_500ml_iv_bag' ||
    itemId === 'normal_saline_500ml_iv_bag' ||
    itemId === 'oral_rehydration_salts_who'
  ) {
    for (const p of Object.values(bodyState)) {
      p.health = Math.min(100, p.health + 10);
    }
    treated = true;
    actionDesc = 'Damar içi elektrolit serum infüzyonu yapıldı: Kan hacmi ve doku perfüzyonu yükseltildi.';
  }

  // 12. Surgical & Diagnostic Tools
  else if (
    itemId === 'trauma_shears_scissors' ||
    itemId === 'surgical_forceps' ||
    itemId === 'surgical_hemostat_forceps' ||
    itemId === 'surgical_scalpel_disposable_10' ||
    itemId === 'bone_saw_gigli_wire' ||
    itemId === 'tissue_forceps_toothed' ||
    itemId === 'dental_extraction_forceps' ||
    itemId === 'dual_head_stethoscope' ||
    itemId === 'aneroid_blood_pressure_cuff' ||
    itemId === 'pulse_oximeter_fingertip' ||
    itemId === 'sterile_disposable_hypodermic_syringes' ||
    itemId === 'iv_giving_infusion_set' ||
    itemId === 'iv_infusion_tubing_set' ||
    itemId === 'iv_cannula_catheter_18g'
  ) {
    if (part.bleeding === BLEED_LEVELS.MINOR) part.bleeding = BLEED_LEVELS.NONE;
    part.infectionRisk = Math.max(0, part.infectionRisk - 25);
    part.health = Math.min(100, part.health + 8);
    treated = true;
    actionDesc = 'Cerrahi/teşhis ekipmanıyla saha müdahalesi gerçekleştirildi: Yabancı cisimler çıkarıldı ve doku temizlendi.';
  }

  // 13. Analgesics, Antidotes & Emergency Injections
  else {
    part.health = Math.min(100, part.health + 5);
    treated = true;
    actionDesc = 'İlaç/antidot uygulandı: Ağrı ve toksik belirtiler hafifletildi.';
  }

  if (treated && bus) {
    bus.emit(EVENT_BODY_UPDATED, { part: targetPart, bodyState, actionDesc });
  }

  return { success: treated, actionDesc };
}

/**
 * Hourly biological degradation, infection proliferation, and hemodynamic blood loss tick.
 */
function tickBodyState(bodyState, hours = 1, { rng = null, bus = null } = {}) {
  if (!bodyState) return { totalBleedLoss: 0, alerts: [] };

  let totalBleedLoss = 0;
  const alerts = [];

  for (const partName of BODY_PARTS) {
    const part = bodyState[partName];
    if (!part) continue;

    // Blood loss calculation
    const bleedRate = BLEED_RATES_PER_HOUR[part.bleeding] || 0;
    if (bleedRate > 0) {
      const bleedLoss = bleedRate * hours;
      totalBleedLoss += bleedLoss;
      part.health = Math.max(0, part.health - bleedLoss * 0.4);

      if (part.bleeding === BLEED_LEVELS.ARTERIAL) {
        alerts.push({
          type: EVENT_BLEEDING_ALERT,
          part: partName,
          text: `Severe pulsatile arterial bleed on ${partName}! Immediate tourniquet required.`,
        });
      }
    }

    // Infection progression if wound is open
    if (part.bleeding !== BLEED_LEVELS.NONE || part.burns || part.punctured) {
      part.infectionRisk = Math.min(100, part.infectionRisk + 2.5 * hours);
      if (part.infectionRisk >= 75) {
        alerts.push({
          type: EVENT_INFECTION_ALERT,
          part: partName,
          text: `Purulent bacterial infection developing on ${partName} (${Math.round(part.infectionRisk)}%).`,
        });
        part.health = Math.max(0, part.health - 2.0 * hours);
      }
    }

    // Natural recovery of healthy closed tissue
    if (part.bleeding === BLEED_LEVELS.NONE && !part.fractures && !part.punctured && part.infectionRisk < 20) {
      part.health = Math.min(100, part.health + 0.8 * hours);
    }
  }

  if (bus && alerts.length > 0) {
    bus.emit(EVENT_BODY_UPDATED, { bodyState, alerts });
  }

  return {
    totalBleedLoss,
    alerts,
  };
}

/**
 * Aggregates all active physiological debuffs produced by the current body trauma state.
 */
function getBodyDebuffs(bodyState) {
  if (!bodyState) {
    return {
      travelTimeMultiplier: 1.0,
      travelCalorieMultiplier: 1.0,
      travelStaminaMultiplier: 1.0,
      weaponAccuracyPenalty: 0.0,
      scavengeSpeedMultiplier: 1.0,
      hasTensionPneumothorax: false,
      maxStaminaCap: 100,
      hasArterialBleed: false,
      totalBleedRate: 0,
      isImmobilized: false,
    };
  }

  let travelTimeMult = 1.0;
  let travelCalorieMult = 1.0;
  let travelStaminaMult = 1.0;
  let accuracyPenalty = 0.0;
  let scavengeMult = 1.0;
  let hasPneumothorax = Boolean(bodyState.torso?.punctured);
  let maxStaminaCap = hasPneumothorax ? 40 : 100;
  let hasArterial = false;
  let totalBleedRate = 0;

  // Leg Damage & Fractures:
  // Leg damage or fracture doubles sector travel time, increases stamina/calorie cost
  const leftLeg = bodyState.leftLeg;
  const rightLeg = bodyState.rightLeg;
  const leftLegCompromised = leftLeg && (leftLeg.fractures || leftLeg.health < 40);
  const rightLegCompromised = rightLeg && (rightLeg.fractures || rightLeg.health < 40);

  if (leftLegCompromised || rightLegCompromised) {
    travelTimeMult *= 2.0; // Doubles sector travel time
    travelCalorieMult *= 1.45; // Increases calorie cost
    travelStaminaMult *= 1.60; // Increases stamina expenditure
  }
  if (leftLegCompromised && rightLegCompromised) {
    travelTimeMult *= 1.5; // Additional compounding penalty if both legs wrecked
  }

  // Arm Damage:
  // Lowers weapon accuracy and scavenging speed
  const leftArm = bodyState.leftArm;
  const rightArm = bodyState.rightArm;
  if (rightArm && (rightArm.fractures || rightArm.health < 50)) {
    accuracyPenalty += 0.25; // Dominant arm penalty
    scavengeMult *= 1.40;
  }
  if (leftArm && (leftArm.fractures || leftArm.health < 50)) {
    accuracyPenalty += 0.12; // Support arm penalty
    scavengeMult *= 1.25;
  }

  // Check Arterial Bleeds across all parts
  for (const p of Object.values(bodyState)) {
    if (p.bleeding === BLEED_LEVELS.ARTERIAL) {
      hasArterial = true;
    }
    totalBleedRate += BLEED_RATES_PER_HOUR[p.bleeding] || 0;
  }

  return {
    travelTimeMultiplier: travelTimeMult,
    travelCalorieMultiplier: travelCalorieMult,
    travelStaminaMultiplier: travelStaminaMult,
    weaponAccuracyPenalty: Math.min(0.60, accuracyPenalty),
    scavengeSpeedMultiplier: scavengeMult,
    hasTensionPneumothorax: hasPneumothorax,
    maxStaminaCap,
    hasArterialBleed: hasArterial,
    totalBleedRate,
    isImmobilized: Boolean(leftLeg?.health === 0 && rightLeg?.health === 0),
  };
}

/**
 * Calculates weighted composite overall body health percentage (0..100).
 */
function getOverallBodyHealth(bodyState) {
  if (!bodyState) return 100;
  let total = 0;
  for (const [part, weight] of Object.entries(VITAL_PART_WEIGHTS)) {
    const hp = bodyState[part]?.health ?? 100;
    total += hp * weight;
  }
  return Math.round(Math.max(0, Math.min(100, total)));
}

/**
 * Automatically selects the most medically urgent target part for a given item.
 */
function getRecommendedTargetPart(bodyState, itemId = '') {
  if (!bodyState) return 'torso';
  if (!itemId || typeof itemId !== 'string') return 'torso';

  // 1. Tourniquets must go on bleeding limbs (arterial prioritized)
  if (itemId === 'combat_tourniquet_cat' || itemId === 'softt_wide_tourniquet' || itemId.includes('tourniquet')) {
    const arterialLimb = ['leftLeg', 'rightLeg', 'leftArm', 'rightArm'].find(
      (part) => bodyState[part]?.bleeding === BLEED_LEVELS.ARTERIAL
    );
    if (arterialLimb) return arterialLimb;
    const bleedingLimb = ['leftLeg', 'rightLeg', 'leftArm', 'rightArm'].find(
      (part) => bodyState[part]?.bleeding !== BLEED_LEVELS.NONE
    );
    if (bleedingLimb) return bleedingLimb;
    return 'leftArm';
  }

  // 2. Chest seal / Decompression needle / Airway always targets torso
  if (
    itemId === 'chest_seal_vented' ||
    itemId === 'chest_seal_twin_pack' ||
    itemId === 'decompression_needle_14g' ||
    itemId === 'nasopharyngeal_airway_28fr'
  ) {
    return 'torso';
  }

  // 3. Splints / Slings target fractured limbs (or head/torso for neck collar)
  if (
    itemId === 'sam_splint_roll' ||
    itemId === 'sam_splint_36inch' ||
    itemId === 'triangular_bandage_sling' ||
    itemId === 'cohesive_flexible_vet_wrap'
  ) {
    const fracturedLimb = ['leftLeg', 'rightLeg', 'leftArm', 'rightArm'].find(
      (part) => bodyState[part]?.fractures
    );
    if (fracturedLimb) return fracturedLimb;
    const lowestLimb = ['leftLeg', 'rightLeg', 'leftArm', 'rightArm'].sort(
      (a, b) => (bodyState[a]?.health ?? 100) - (bodyState[b]?.health ?? 100)
    )[0];
    return lowestLimb || 'leftLeg';
  }

  if (itemId === 'cervical_extrication_collar') {
    return 'head';
  }

  // 4. Burn treatments target burned parts first
  if (
    itemId.includes('burn') ||
    itemId === 'silver_sulfadiazine_burn_cream' ||
    itemId === 'calamine_lotion_bottle' ||
    itemId === 'hydrocortisone_cream_1pct'
  ) {
    const burnedPart = BODY_PARTS.find((p) => bodyState[p]?.burns);
    if (burnedPart) return burnedPart;
  }

  // 5. Antiseptics target parts with highest infection risk
  if (
    itemId === 'antiseptic' ||
    itemId.includes('iodine') ||
    itemId.includes('chlorhexidine') ||
    itemId.includes('alcohol') ||
    itemId.includes('peroxide')
  ) {
    const infectedPart = [...BODY_PARTS].sort(
      (a, b) => (bodyState[b]?.infectionRisk ?? 0) - (bodyState[a]?.infectionRisk ?? 0)
    )[0];
    if (bodyState[infectedPart]?.infectionRisk > 0) return infectedPart;
  }

  // 6. Hemostatic gauze / bandages / sutures target the part with most severe bleeding
  let worstBleedPart = null;
  for (const partName of BODY_PARTS) {
    if (bodyState[partName]?.bleeding === BLEED_LEVELS.ARTERIAL) {
      worstBleedPart = partName;
      break;
    }
  }
  if (!worstBleedPart) {
    worstBleedPart = BODY_PARTS.find((p) => bodyState[p]?.bleeding === BLEED_LEVELS.MINOR);
  }
  if (worstBleedPart) return worstBleedPart;

  // 7. Otherwise target lowest health part
  let lowestHpPart = 'torso';
  let minHp = 100;
  for (const partName of BODY_PARTS) {
    const hp = bodyState[partName]?.health ?? 100;
    if (hp < minHp) {
      minHp = hp;
      lowestHpPart = partName;
    }
  }
  return lowestHpPart;
}

/**
 * Checks for instantly fatal conditions (e.g. brain death from head collapse or heart rupture).
 */
function isBodyConditionFatal(bodyState) {
  if (!bodyState) return false;
  if ((bodyState.head?.health ?? 100) <= 0) return true;
  if ((bodyState.torso?.health ?? 100) <= 0) return true;
  return false;
}


  // --- src/modules/inventory/index.js ---









const EQUIP_MINUTES = 5;
const itemName = (itemId) => ref(`item.${itemId}.name`);

function createStartingInventory() {
  let inventory = { stacks: [], equipment: { ...BALANCE.startingEquipment }, ground: {} };
  for (const { itemId, qty } of BALANCE.startingKit) inventory = addItem(inventory, itemId, qty).inventory;
  return inventory;
}

/** Treatment items are refused when they would do nothing, instead of silently wasting them. */
function wouldBeWasted(item, player, itemId = '') {
  if (!item.use || !item.use.effects) return true;
  const effects = item.use.effects;
  const body = player.body || {};
  const parts = Object.values(body);

  let hasTreatableCondition = false;

  for (const eff of effects) {
    if (eff.type === 'heal') {
      if (player.health < 100 || parts.some((p) => p.health < 100)) {
        hasTreatableCondition = true;
      }
    } else if (eff.type === 'vital') {
      const current = player[eff.vital];
      if (current != null && current < 100) {
        hasTreatableCondition = true;
      }
    } else if (eff.type === 'cure') {
      const id = eff.id;
      if (player.ailments && player.ailments[id]) {
        hasTreatableCondition = true;
      }
      if (id === 'bleeding' && (player.ailments?.bleeding || parts.some((p) => p.bleeding && p.bleeding !== 'none'))) {
        hasTreatableCondition = true;
      }
      if (id === 'infection' && (player.ailments?.infection || parts.some((p) => (p.infectionRisk || 0) > 0))) {
        hasTreatableCondition = true;
      }
      if (id === 'infectionRisk' && parts.some((p) => (p.infectionRisk || 0) > 0)) {
        hasTreatableCondition = true;
      }
      if ((id === 'sprain' || id === 'fracture') && (player.ailments?.sprain || parts.some((p) => p.fractures))) {
        hasTreatableCondition = true;
      }
      if (id === 'burn' && parts.some((p) => p.burns)) {
        hasTreatableCondition = true;
      }
      if ((id === 'puncture' || id === 'pneumothorax') && body.torso?.punctured) {
        hasTreatableCondition = true;
      }
      if (id === 'pain' && (player.ailments?.pain || parts.some((p) => p.health < 80 || p.fractures || p.burns))) {
        hasTreatableCondition = true;
      }
      if (id === 'poison' && player.ailments?.poison) {
        hasTreatableCondition = true;
      }
      if (id === 'fever' && (player.ailments?.fever || player.ailments?.infection)) {
        hasTreatableCondition = true;
      }
      if (id === 'parasites' || id === 'malaria') {
        hasTreatableCondition = true;
      }
    } else if (eff.type === 'stat') {
      hasTreatableCondition = true;
    }
  }

  if (item.category === 'medical') {
    if (hasTreatableCondition) return false;
    const target = getRecommendedTargetPart(body, itemId);
    const probe = applyMedicalTreatment(JSON.parse(JSON.stringify(body)), itemId, target);
    if (probe.success) return false;

    return true;
  }

  const onlyCures = effects.every((eff) => eff.type === 'cure');
  if (onlyCures && !hasTreatableCondition) return true;

  return false;
}

/** Puts items in the pack; whatever does not fit is dropped where the player stands. */
function grantItems({ store, engine }, itemId, qty) {
  const accepted = store.commit('inventory/add', { itemId, qty });
  if (accepted > 0) engine.log('log.inventory.gained', { item: itemName(itemId), count: accepted }, 'good');
  const overflow = qty - accepted;
  if (overflow > 0) {
    store.commit('inventory/toGround', { nodeId: store.state.world.currentNodeId, itemId, qty: overflow });
    engine.log('log.inventory.left_behind', { item: itemName(itemId), count: overflow }, 'warn');
  }
}

function registerInventoryMutations(store) {
  store.registerMutations('inventory', {
    add(state, { itemId, qty }) {
      const result = addItem(state.inventory, itemId, qty);
      state.inventory = result.inventory;
      return result.accepted;
    },
    remove(state, { itemId, qty }) {
      const result = removeItem(state.inventory, itemId, qty);
      state.inventory = result.inventory;
      return result.removed;
    },
    equip(state, { itemId }) {
      state.inventory = equipItem(state.inventory, itemId).inventory;
    },
    unequip(state, { slot }) {
      state.inventory = unequipSlot(state.inventory, slot).inventory;
    },
    toGround(state, { nodeId, itemId, qty }) {
      state.inventory = addToGround(state.inventory, nodeId, itemId, qty);
    },
    fromGround(state, { nodeId, itemId, qty }) {
      const result = removeFromGround(state.inventory, nodeId, itemId, qty);
      state.inventory = result.inventory;
      return result.removed;
    },
  });
}

function registerInventoryActions(engine) {
  engine.registerAction('inventory/use', ({ itemId }, ctx) => {
    const { store, effects } = ctx;
    const item = getItem(itemId);
    if (!item.use) return { ok: false, reason: 'reject.not_usable' };
    if (countItem(store.state.inventory, itemId) < 1) return { ok: false, reason: 'reject.missing_item' };
    if (wouldBeWasted(item, store.state.player, itemId)) return { ok: false, reason: 'reject.nothing_to_treat' };

    store.commit('inventory/remove', { itemId, qty: 1 });
    engine.log('log.inventory.used', { item: itemName(itemId) });

    if (item.category === 'medical') {
      codexManager.trackCareer('totalMedicalTreatments', 1);
      if (itemId.includes('tourniquet') || itemId.includes('splint') || itemId.includes('chest_seal') || itemId.includes('ciprofloxacin')) {
        codexManager.unlockAchievement('trauma_surgeon');
      }
      if (store.state.player.body) {
        const target = getRecommendedTargetPart(store.state.player.body, itemId);
        const res = applyMedicalTreatment(store.state.player.body, itemId, target, { bus: ctx.bus });
        if (res.actionDesc) {
          engine.log(res.actionDesc, {}, 'good');
        }
      }
    }

    effects.apply(item.use.effects, ctx, { kind: 'item', itemId });
    engine.advanceTime(item.use.minutes);
    return { ok: true };
  }, { allowDuringEncounter: true });

  engine.registerAction('inventory/drop', ({ itemId, qty = 1 }, { store }) => {
    const removed = store.commit('inventory/remove', { itemId, qty });
    if (removed === 0) return { ok: false, reason: 'reject.missing_item' };
    store.commit('inventory/toGround', { nodeId: store.state.world.currentNodeId, itemId, qty: removed });
    engine.log('log.inventory.dropped', { item: itemName(itemId), count: removed });
    return { ok: true };
  });

  engine.registerAction('inventory/pickup', ({ itemId, qty = 1 }, { store }) => {
    const nodeId = store.state.world.currentNodeId;
    const planned = addItem(store.state.inventory, itemId, qty);
    if (planned.accepted === 0) {
      return { ok: false, reason: planned.reason === 'weight' ? 'reject.too_heavy' : 'reject.no_room' };
    }
    const lifted = store.commit('inventory/fromGround', { nodeId, itemId, qty: planned.accepted });
    store.commit('inventory/add', { itemId, qty: lifted });
    engine.log('log.inventory.picked_up', { item: itemName(itemId), count: lifted });
    return { ok: true };
  });

  engine.registerAction('inventory/equip', ({ itemId }, { store }) => {
    const result = equipItem(store.state.inventory, itemId);
    if (result.error) return { ok: false, reason: result.error };
    store.commit('inventory/equip', { itemId });
    engine.log('log.inventory.equipped', { item: itemName(itemId) });
    engine.advanceTime(EQUIP_MINUTES);
    return { ok: true };
  });

  engine.registerAction('inventory/unequip', ({ slot }, { store }) => {
    const result = unequipSlot(store.state.inventory, slot);
    if (result.error) return { ok: false, reason: result.error };
    store.commit('inventory/unequip', { slot });
    engine.log('log.inventory.unequipped', { item: itemName(result.itemId) });
    engine.advanceTime(EQUIP_MINUTES);
    return { ok: true };
  });
}

function registerInventoryEffects(effects, ctx) {
  const { store, rng, engine } = ctx;

  effects.register('loot', ({ table, rolls = 1 }) => {
    const found = rollLoot(rng, table, rollRange(rng, rolls));
    for (const { itemId, qty } of found) grantItems(ctx, itemId, qty);
  });

  effects.register('give', ({ itemId, qty = 1 }) => grantItems(ctx, itemId, qty));

  effects.register('take', ({ qty = 1, random, ...matcher }) => {
    for (let taken = 0; taken < qty; taken += 1) {
      const candidates = random
        ? store.state.inventory.stacks
        : matchingStacks(store.state.inventory, matcher);
      if (candidates.length === 0) {
        if (taken === 0) engine.log('log.inventory.nothing_to_lose', {}, 'plain');
        return;
      }
      const { itemId } = rng.pick(candidates);
      store.commit('inventory/remove', { itemId, qty: 1 });
      engine.log('log.inventory.lost', { item: itemName(itemId), count: 1 }, 'bad');
    }
  });
}

const inventoryModule = {
  id: 'inventory',
  createState: createStartingInventory,

  install(ctx) {
    registerInventoryMutations(ctx.store);
    registerInventoryActions(ctx.engine);
    registerInventoryEffects(ctx.effects, ctx);
  },
};


  // --- src/data/ailments.js ---
/**
 * Ailment rules. Runtime instances live in `player.ailments[id]` and carry a
 * single magnitude field: `severity` (bleeding), `progress` (infection) or
 * `hours` remaining (sprain).
 */
const AILMENTS = {
  bleeding: {
    glyph: '♦',
    tone: 'bad',
    initial: { severity: 1 },
    maxSeverity: 3,
    healthPerHourPerSeverity: 1.2,
    stopChancePerHour: 0.20,
    infectionChancePerHour: 0.03,
  },
  infection: {
    glyph: '☣',
    tone: 'bad',
    initial: { progress: 10 },
    growthPerHour: 1.0,
    recoveryPerHour: 1.2,
    recoveryBelow: 30,
    symptomaticAt: 35,
    severeAt: 80,
    healthPerHourSymptomatic: 0.8,
    healthPerHourSevere: 2.5,
    energyPerHourSymptomatic: 0.8,
  },
  sprain: {
    glyph: '⌇',
    tone: 'warn',
    initial: { hours: 24 },
    travelTimeMultiplier: 1.15,
  },
  pain: {
    glyph: '⚡',
    tone: 'warn',
    initial: { severity: 2 },
    maxSeverity: 5,
    decayPerHour: 0.5,
    travelTimeMultiplier: 1.10,
  },
  poison: {
    glyph: '☠',
    tone: 'bad',
    initial: { severity: 25 },
    maxSeverity: 100,
    healthPerHour: 1.5,
    decayPerHour: 1.0,
  },
};



  // --- src/modules/inventory/inventorySelectors.js ---






const UNARMED_POWER = 1;

function loadSummary(state) {
  const { inventory, player } = state;
  const extraKg = player?.trait === 'hoarder' ? 2.5 : 0;
  const limits = capacity(inventory);
  const totalKg = limits.kg + extraKg;
  const weight = carriedWeight(inventory);
  return {
    weight,
    capacityKg: totalKg,
    hardLimitKg: totalKg * BALANCE.inventory.hardLimitRatio,
    slotsUsed: inventory.stacks.length,
    slotsTotal: limits.slots,
    overloaded: weight > totalKg,
  };
}

const isOverloaded = (state) => loadSummary(state).overloaded;

function weaponProfile(state) {
  const weaponId = state.inventory.equipment.weapon;
  if (!weaponId) return { itemId: null, power: UNARMED_POWER, ammoId: null, loaded: true };
  const { power, ammo, unloadedPower } = getItem(weaponId).equip;
  const loaded = !ammo || countItem(state.inventory, ammo) > 0;
  return { itemId: weaponId, power: loaded ? power : unloadedPower, ammoId: ammo ?? null, loaded };
}

function combatRating(state) {
  return weaponProfile(state).power + skillLevel(state, 'marksmanship') * SKILLS.marksmanship.bonusPerLevel;
}

function armorValue(state) {
  const bodyId = state.inventory.equipment.body;
  return bodyId ? getItem(bodyId).equip.armor ?? 0 : 0;
}

function incomingDamageMultiplier(state) {
  return Math.max(0.4, 1 - armorValue(state) * BALANCE.inventory.armorDamageReduction);
}

const passiveBonus = (state, key) => passiveTotal(state.inventory, key);
const hasGearFlag = (state, flag) => hasEquippedFlag(state.inventory, flag);
const groundHere = (state) => groundAt(state.inventory, state.world.currentNodeId);

function meetsRequirement(state, requires) {
  if (!requires) return true;
  return matchingStacks(state.inventory, requires).length > 0;
}



  // --- src/modules/status/statusSelectors.js ---




const VITALS = ['health', 'satiety', 'hydration', 'energy'];
const NEEDS = ['satiety', 'hydration', 'energy'];

function vitalBand(value) {
  const { fine, low, critical } = BALANCE.vitals.bands;
  if (value >= fine) return 'fine';
  if (value >= low) return 'low';
  if (value >= critical) return 'critical';
  return 'depleted';
}

function isSymptomatic(player) {
  const infection = player.ailments.infection;
  return Boolean(infection && infection.progress >= AILMENTS.infection.symptomaticAt);
}

function canRegenerate(player) {
  const { requires } = BALANCE.regeneration;
  return !player.ailments.bleeding
    && !isSymptomatic(player)
    && player.satiety >= requires.satiety
    && player.hydration >= requires.hydration;
}

/** Multiplier (>1 means slower) applied to journey duration by the body's condition. */
function statusTravelMultiplier(state) {
  const { player } = state;
  let multiplier = 1;
  if (player.energy < BALANCE.travel.exhaustedThreshold) multiplier *= BALANCE.travel.exhaustedTimeMultiplier;
  if (player.ailments.sprain) multiplier *= AILMENTS.sprain.travelTimeMultiplier;
  if (player.ailments.pain) multiplier *= (AILMENTS.pain?.travelTimeMultiplier || 1.10);
  if (player.body) {
    const debuffs = getBodyDebuffs(player.body);
    multiplier *= debuffs.travelTimeMultiplier;
  }
  return multiplier;
}

/** Ailment magnitude normalised to 0..1 for meters. */
function ailmentIntensity(id, data) {
  switch (id) {
    case 'bleeding': return data.severity / AILMENTS.bleeding.maxSeverity;
    case 'infection': return data.progress / 100;
    case 'sprain': return Math.min(1, data.hours / AILMENTS.sprain.initial.hours);
    case 'pain': return Math.min(1, (data.severity || 1) / (AILMENTS.pain?.maxSeverity || 5));
    case 'poison': return Math.min(1, (data.severity || 1) / (AILMENTS.poison?.maxSeverity || 100));
    default: return 0.5;
  }
}



  // --- src/modules/status/index.js ---









const BAND_ORDER = ['fine', 'low', 'critical', 'depleted'];
const DEPRIVATION_CAUSE = { satiety: 'starvation', hydration: 'dehydration', energy: 'exhaustion' };
const clampVital = (value) => Math.max(0, Math.min(BALANCE.vitals.max, value));

function createPlayer() {
  return {
    name: 'Survivor',
    age: 28,
    bloodType: 'A+',
    trait: 'stoic',
    archetype: 'scavenger',
    ...BALANCE.vitals.start,
    body: createDefaultBodyState(),
    ailments: {},
    alive: true,
    causeOfDeath: null,
    diedAt: null,
  };
}

/** Changes a vital and narrates the moment it slides into a worse band. */
function adjustVital({ store, engine }, vital, delta) {
  const before = store.state.player[vital];
  const applied = store.commit('player/changeVital', { vital, delta });
  const fromBand = vitalBand(before);
  const toBand = vitalBand(store.state.player[vital]);
  if (BAND_ORDER.indexOf(toBand) > BAND_ORDER.indexOf(fromBand)) {
    engine.log(`log.vital.${vital}.${toBand}`, {}, toBand === 'low' ? 'warn' : 'bad');
  }
  return applied;
}

function inflictDamage(ctx, amount, cause) {
  if (amount <= 0 || !ctx.store.state.player.alive) return 0;
  const dealt = -adjustVital(ctx, 'health', -amount);
  if (ctx.store.state.player.health <= 0) {
    ctx.store.commit('player/die', { cause });
    ctx.engine.log(`death.cause.${cause}`, {}, 'bad');
    ctx.bus.emit('player:died', { cause });
  }
  return dealt;
}

function tickBleeding(ctx, bleeding, hours, harm) {
  const { store, rng, engine } = ctx;
  const rules = AILMENTS.bleeding;
  harm.add('bleeding', bleeding.severity * rules.healthPerHourPerSeverity * hours);

  const stopChance = (rules.stopChancePerHour * skillMultiplier(store.state, 'medical') * hours) / bleeding.severity;
  if (rng.chance(stopChance)) {
    store.commit('player/clearAilment', 'bleeding');
    engine.log('log.ailment.bleeding.stopped', {}, 'good');
    return;
  }
  if (!store.state.player.ailments.infection && rng.chance(rules.infectionChancePerHour * hours)) {
    store.commit('player/setAilment', { id: 'infection', data: { ...AILMENTS.infection.initial } });
    engine.log('log.ailment.infection.gained', {}, 'bad');
  }
}

function tickInfection(ctx, infection, hours, harm) {
  const { store, engine } = ctx;
  const rules = AILMENTS.infection;
  const { player } = store.state;
  const fightingItOff = infection.progress < rules.recoveryBelow && player.satiety > 60 && player.hydration > 60;

  const progress = fightingItOff
    ? infection.progress - rules.recoveryPerHour * hours
    : Math.min(100, infection.progress + rules.growthPerHour * hours);

  if (progress <= 0) {
    store.commit('player/clearAilment', 'infection');
    engine.log('log.ailment.infection.cleared', {}, 'good');
    return;
  }
  store.commit('player/setAilment', { id: 'infection', data: { progress } });

  if (infection.progress < rules.symptomaticAt && progress >= rules.symptomaticAt) {
    engine.log('log.ailment.infection.symptomatic', {}, 'bad');
  }
  if (infection.progress < rules.severeAt && progress >= rules.severeAt) {
    engine.log('log.ailment.infection.severe', {}, 'bad');
  }
  if (progress >= rules.severeAt) harm.add('infection', rules.healthPerHourSevere * hours);
  else if (progress >= rules.symptomaticAt) harm.add('infection', rules.healthPerHourSymptomatic * hours);
  if (progress >= rules.symptomaticAt) adjustVital(ctx, 'energy', -rules.energyPerHourSymptomatic * hours);
}

function tickSprain(ctx, sprain, hours) {
  const remaining = sprain.hours - hours;
  if (remaining <= 0) {
    ctx.store.commit('player/clearAilment', 'sprain');
    ctx.engine.log('log.ailment.sprain.healed', {}, 'good');
    return;
  }
  ctx.store.commit('player/setAilment', { id: 'sprain', data: { hours: remaining } });
}

function tickPain(ctx, pain, hours) {
  const rules = AILMENTS.pain;
  const decay = (rules?.decayPerHour || 0.5) * hours;
  const remaining = (pain.severity || 1) - decay;
  if (remaining <= 0) {
    ctx.store.commit('player/clearAilment', 'pain');
    ctx.engine.log('log.ailment.pain.healed', {}, 'good');
    return;
  }
  ctx.store.commit('player/setAilment', { id: 'pain', data: { severity: remaining } });
}

function tickPoison(ctx, poison, hours, harm) {
  const rules = AILMENTS.poison;
  harm.add('poison', (rules?.healthPerHour || 1.5) * hours);
  const decay = (rules?.decayPerHour || 1.0) * hours;
  const remaining = (poison.severity || 10) - decay;
  if (remaining <= 0) {
    ctx.store.commit('player/clearAilment', 'poison');
    ctx.engine.log('log.ailment.poison.healed', {}, 'good');
    return;
  }
  ctx.store.commit('player/setAilment', { id: 'poison', data: { severity: remaining } });
}

/** Accumulates damage per cause so a death can be attributed to the worst one. */
function createHarmLedger() {
  const byCause = new Map();
  return {
    add(cause, amount) {
      byCause.set(cause, (byCause.get(cause) ?? 0) + amount);
    },
    total: () => [...byCause.values()].reduce((sum, amount) => sum + amount, 0),
    worstCause: () => [...byCause].sort((a, b) => b[1] - a[1])[0]?.[0],
    isEmpty: () => byCause.size === 0,
  };
}

function tickStatus(ctx, { hours, activity }) {
  const { store } = ctx;
  if (!store.state.player.alive) return;

  const profile = BALANCE.activities[activity] ?? BALANCE.activities.idle;
  const overloadDrain = activity === 'travel' && isOverloaded(store.state)
    ? BALANCE.inventory.overloadEnergyDrain
    : 1;

  for (const need of NEEDS) {
    let delta = profile[need] * hours;
    if (need === 'energy' && delta < 0) delta *= overloadDrain;
    adjustVital(ctx, need, delta);
  }

  const harm = createHarmLedger();
  for (const need of NEEDS) {
    if (store.state.player[need] <= 0) harm.add(DEPRIVATION_CAUSE[need], BALANCE.deprivationDamage[need] * hours);
  }

  const { ailments } = store.state.player;
  if (ailments.bleeding) tickBleeding(ctx, ailments.bleeding, hours, harm);
  if (ailments.infection) tickInfection(ctx, ailments.infection, hours, harm);
  if (ailments.sprain) tickSprain(ctx, ailments.sprain, hours);
  if (ailments.pain) tickPain(ctx, ailments.pain, hours);
  if (ailments.poison) tickPoison(ctx, ailments.poison, hours, harm);

  if (store.state.player.body) {
    const bodyTick = tickBodyState(store.state.player.body, hours, { rng: ctx.rng, bus: ctx.bus });
    if (bodyTick.totalBleedLoss > 0) {
      harm.add('bleeding', bodyTick.totalBleedLoss);
    }
    if (isBodyConditionFatal(store.state.player.body)) {
      harm.add('critical_organ_failure', 999);
    }
    const debuffs = getBodyDebuffs(store.state.player.body);
    if (activity === 'travel') {
      if (debuffs.travelCalorieMultiplier > 1) {
        adjustVital(ctx, 'satiety', -(profile.satiety * (debuffs.travelCalorieMultiplier - 1) * hours));
      }
      if (debuffs.travelStaminaMultiplier > 1) {
        adjustVital(ctx, 'energy', -(profile.energy * (debuffs.travelStaminaMultiplier - 1) * hours));
      }
    }
    if (debuffs.hasTensionPneumothorax && store.state.player.energy > debuffs.maxStaminaCap) {
      store.commit('player/changeVital', { vital: 'energy', delta: debuffs.maxStaminaCap - store.state.player.energy });
    }
  }

  if (harm.isEmpty() && canRegenerate(store.state.player)) {
    let rate = activity === 'rest' ? BALANCE.regeneration.rest : BALANCE.regeneration.idle;
    if (store.state.player.trait === 'fast_metabolism') rate *= 1.25;
    adjustVital(ctx, 'health', rate * hours);
  }
  if (!harm.isEmpty()) inflictDamage(ctx, harm.total(), harm.worstCause());
}

function registerStatusEffects(ctx) {
  const { effects, store, rng, engine } = ctx;

  effects.register('vital', ({ vital, amount }) => {
    const applied = adjustVital(ctx, vital, amount);
    if (Math.round(applied) === 0) return;
    const key = applied > 0 ? 'log.effect.vital_up' : 'log.effect.vital_down';
    engine.log(key, { vital: ref(`status.vital.${vital}`), amount: Math.abs(Math.round(applied)) });
  });

  effects.register('heal', ({ amount }, _context, source) => {
    const healed = adjustVital(ctx, 'health', rollRange(rng, amount) * skillMultiplier(store.state, 'medical'));
    engine.log('log.effect.healed', { amount: Math.round(healed) }, 'good');
    const itemId = source?.itemId;
    if (store.state.player.body && itemId) {
      const target = getRecommendedTargetPart(store.state.player.body, itemId);
      const res = applyMedicalTreatment(store.state.player.body, itemId, target, { bus: ctx.bus });
      if (res.actionDesc) {
        engine.log(res.actionDesc, {}, 'good');
      }
    }
  });

  effects.register('stat', ({ id, amount }) => {
    if (id === 'stamina' || id === 'energy') {
      adjustVital(ctx, 'energy', amount);
      engine.log('log.effect.vital_up', { vital: ref('status.vital.energy'), amount: Math.round(amount) });
    } else if (id === 'thirst' || id === 'hydration') {
      adjustVital(ctx, 'hydration', amount);
      engine.log('log.effect.vital_up', { vital: ref('status.vital.hydration'), amount: Math.round(amount) });
    } else if (id === 'hunger' || id === 'satiety') {
      adjustVital(ctx, 'satiety', amount);
      engine.log('log.effect.vital_up', { vital: ref('status.vital.satiety'), amount: Math.round(amount) });
    } else if (id === 'morale') {
      adjustVital(ctx, 'energy', amount * 0.5);
      engine.log('log.effect.morale_boost', { amount: Math.round(amount) }, 'good');
    } else if (id === 'radResistance') {
      engine.log('log.effect.rad_resistance', { amount: Math.round(amount) }, 'good');
    }
  });

  effects.register('damage', ({ amount, cause = 'wounds', part = null, damageType = null }) => {
    const raw = rollRange(rng, amount) * incomingDamageMultiplier(store.state);
    const dealt = inflictDamage(ctx, Math.max(1, Math.round(raw)), cause);
    if (store.state.player.alive) {
      engine.log('log.effect.damaged', { amount: Math.round(dealt) }, 'bad');
      if (store.state.player.body) {
        applyBodyDamage(store.state.player.body, {
          part,
          amount: Math.round(dealt),
          damageType: damageType || (cause === 'burn' ? 'burn' : 'blunt'),
          rng,
          bus: ctx.bus,
        });
      }
    }
  });

  effects.register('ailment', ({ id, severity = 1 }) => {
    const current = store.state.player.ailments[id];
    const rules = AILMENTS[id];
    if (!rules) return;
    let data;
    if (id === 'bleeding') {
      data = { severity: Math.min(rules.maxSeverity, (current?.severity ?? 0) + severity) };
    } else if (id === 'infection') {
      data = { progress: Math.min(100, (current?.progress ?? 0) + rules.initial.progress) };
    } else if (id === 'pain') {
      data = { severity: Math.min(rules.maxSeverity, (current?.severity ?? 0) + severity) };
    } else if (id === 'poison') {
      data = { severity: Math.min(rules.maxSeverity, (current?.severity ?? 0) + severity) };
    } else {
      data = { ...rules.initial };
    }
    store.commit('player/setAilment', { id, data });
    engine.log(current ? `log.ailment.${id}.worse` : `log.ailment.${id}.gained`, {}, 'bad');
  });

  effects.register('cure', ({ id, amount }, _context, source) => {
    const itemId = source?.itemId;
    if (store.state.player.body && itemId) {
      const target = getRecommendedTargetPart(store.state.player.body, itemId);
      const res = applyMedicalTreatment(store.state.player.body, itemId, target, { bus: ctx.bus });
      if (res.actionDesc) {
        engine.log(res.actionDesc, {}, 'good');
      }
    }

    // Direct trauma clearance if item cures trauma flags
    if (store.state.player.body) {
      const body = store.state.player.body;
      if (id === 'bleeding') {
        for (const p of Object.values(body)) {
          if (p.bleeding === 'minor') p.bleeding = 'none';
        }
      } else if (id === 'fracture') {
        for (const p of Object.values(body)) {
          p.fractures = false;
        }
      } else if (id === 'burn') {
        for (const p of Object.values(body)) {
          p.burns = false;
        }
      } else if (id === 'puncture' || id === 'pneumothorax') {
        if (body.torso) body.torso.punctured = false;
      } else if (id === 'infection' || id === 'infectionRisk') {
        for (const p of Object.values(body)) {
          p.infectionRisk = Math.max(0, p.infectionRisk - (amount || 50));
        }
      }
    }

    const current = store.state.player.ailments[id];
    if (!current) return;
    if (!AILMENTS[id]) {
      store.commit('player/clearAilment', id);
      return;
    }
    const field = Object.keys(AILMENTS[id].initial)[0];
    const remaining = amount == null ? 0 : current[field] - amount * skillMultiplier(store.state, 'medical');
    if (remaining <= 0) {
      store.commit('player/clearAilment', id);
      engine.log(`log.ailment.${id}.cured`, {}, 'good');
    } else {
      store.commit('player/setAilment', { id, data: { [field]: remaining } });
      engine.log(`log.ailment.${id}.treated`, {}, 'good');
    }
  });
}

const statusModule = {
  id: 'player',
  createState: createPlayer,

  install(ctx) {
    const { store, bus, engine } = ctx;

    store.registerMutations('player', {
      changeVital(state, { vital, delta }) {
        const before = state.player[vital];
        state.player[vital] = clampVital(before + delta);
        return state.player[vital] - before;
      },
      setAilment(state, { id, data }) {
        state.player.ailments[id] = data;
      },
      clearAilment(state, id) {
        delete state.player.ailments[id];
      },
      setProfile(state, { name, age, bloodType, trait, archetype }) {
        if (name !== undefined) state.player.name = name;
        if (age !== undefined) state.player.age = age;
        if (bloodType !== undefined) state.player.bloodType = bloodType;
        if (trait !== undefined) state.player.trait = trait;
        if (archetype !== undefined) state.player.archetype = archetype;
      },
      die(state, { cause }) {
        state.player.alive = false;
        state.player.health = 0;
        state.player.causeOfDeath = cause;
        state.player.diedAt = state.time.minutes;
      },
      applyBodyTrauma(state, params) {
        if (!state.player.body) state.player.body = createDefaultBodyState();
        return applyBodyDamage(state.player.body, params);
      },
      treatBodyPart(state, { itemId, targetPart }) {
        if (!state.player.body) state.player.body = createDefaultBodyState();
        return applyMedicalTreatment(state.player.body, itemId, targetPart);
      },
      updateBody(state, bodyState) {
        state.player.body = bodyState;
      },
    });

    engine.addGuard((type, options, state) => (state.player.alive ? null : 'reject.dead'));
    bus.on('time:tick', (tick) => tickStatus(ctx, tick));
    registerStatusEffects(ctx);
  },
};



