/**
 * Returns a random field log for scavenge discovery.
 */
function getRandomFieldLog(rng) {
  if (!rng || !FIELD_LOGS.length) return FIELD_LOGS[0];
  const idx = rng.int(0, FIELD_LOGS.length - 1);
  return FIELD_LOGS[idx];
}



