const BLOOD_TYPES = ['0-', '0+', 'A-', 'A+', 'B-', 'B+', 'AB-', 'AB+'];

const TRAITS = {
  stoic: {
    id: 'stoic',
    glyph: '◆',
  },
  night_owl: {
    id: 'night_owl',
    glyph: '☽',
  },
  fast_metabolism: {
    id: 'fast_metabolism',
    glyph: '⚕',
  },
  hoarder: {
    id: 'hoarder',
    glyph: '▤',
  },
  iron_stomach: {
    id: 'iron_stomach',
    glyph: '🛡',
  },
};

const RANDOM_NAMES = [
  'Deniz',
  'Kerem',
  'Elena',
  'Viktor',
  'Mara',
  'Marcus',
  'Leyla',
  'Nora',
  'Barış',
  'Zehra',
  'Roland',
  'Sarp',
  'Maya',
  'Kaan',
  'Selin',
  'Jax',
  'Silas',
  'Tariq',
  'Cem',
  'Bora',
  'Derya',
  'Aylin',
  'Vera',
  'Iskandar',
];

function getRandomName(exclude = '') {
  const pool = RANDOM_NAMES.filter((name) => name !== exclude);
  return pool[Math.floor(Math.random() * pool.length)] || 'Survivor';
}

function getAgeBracket(age) {
  if (age <= 25) return 'young';
  if (age <= 40) return 'prime';
  return 'veteran';
}



  // --- src/ui/menuView.js ---








class MenuView {
  #root;
  #onContinue;
  #onStartNew;
  #onLocaleChange;
  #saveManager;
  #pwaManager;
  #onLoadSlot;
  #onSaveSlot;
  #onDeleteSlot;
  #onResetAll;
  #onOpenCodex;

  #name = 'Mara';
  #age = 28;
  #bloodType = 'A+';
  #selectedTrait = 'stoic';
  #selectedArchetype = 'scavenger';
  #selectedLocation = 'istanbul';
  #hasSave = false;
  #savedState = null;

  #mode = 'menu'; // 'menu' | 'create' | 'load_game' | 'settings' | 'exit_confirm' | 'terminated'
  #currentStep = 1; // 1: Identity, 2: Archetype, 3: Sector, 4: Summary
  #lastRenderedStep = 1;
  #lastRenderedMode = 'menu';
  #isPremiumModalOpen = false;
  #slotActionFeedback = '';

  constructor({
    root,
    onContinue,
    onStartNew,
    onLocaleChange,
    saveManager,
    pwaManager,
    onLoadSlot,
    onSaveSlot,
    onDeleteSlot,
    onResetAll,
    onOpenCodex,
  }) {
    this.#root = root;
    this.#onContinue = onContinue;
    this.#onStartNew = onStartNew;
    this.#onLocaleChange = onLocaleChange;
    this.#saveManager = saveManager;
    this.#pwaManager = pwaManager;
    this.#onLoadSlot = onLoadSlot;
    this.#onSaveSlot = onSaveSlot;
    this.#onDeleteSlot = onDeleteSlot;
    this.#onResetAll = onResetAll;
    this.#onOpenCodex = onOpenCodex;
  }

  get isOpen() {
    return !this.#root.hidden;
  }

  open({ hasSave, state, mode } = {}) {
    this.#hasSave = Boolean(hasSave && state?.player?.alive);
    this.#savedState = state;
    this.#mode = mode || 'menu';
    this.#currentStep = 1;
    this.#isPremiumModalOpen = false;
    this.#slotActionFeedback = '';
    this.#root.hidden = false;
    document.body?.classList.add('is-menu-open');
    this.render();
  }

  close() {
    this.#root.hidden = true;
    document.body?.classList.remove('is-menu-open');
  }

  render() {
    if (this.#root.hidden) return;

    const prevBody = this.#root.querySelector('.menu-body');
    const prevScrollTop = prevBody ? prevBody.scrollTop : 0;
    const isSameStepAndMode = this.#lastRenderedMode === this.#mode && this.#lastRenderedStep === this.#currentStep;

    const localeBtn = el(
      'button',
      {
        type: 'button',
        class: 'menu-locale-toggle-btn',
        title: i18n.locale === 'tr' ? 'Switch to English' : 'Türkçe Dilini Seç',
        onClick: () => {
          const nextLocale = i18n.locale === 'tr' ? 'en' : 'tr';
          this.#onLocaleChange(nextLocale);
        },
      },
      el('span', { class: 'menu-locale-icon' }, '🌐'),
      el('span', { class: 'menu-locale-code' }, (i18n.locale || 'en').toUpperCase()),
    );

    const isCreate = this.#mode === 'create';
    const isLoadGame = this.#mode === 'load_game';
    const isSettings = this.#mode === 'settings';
    const isExitConfirm = this.#mode === 'exit_confirm';
    const isTerminated = this.#mode === 'terminated';

    let signalLabel = t('menu.kicker');
    if (isCreate) signalLabel = t('character.create_title');
    else if (isLoadGame) signalLabel = t('menu.slots.title');
    else if (isSettings) signalLabel = t('menu.settings.title');
    else if (isExitConfirm || isTerminated) signalLabel = t('menu.exit.title');

    let loreText = t('menu.lore');
    if (isCreate) loreText = t(`character.step_subtitle.${this.#currentStep}`);
    else if (isLoadGame) loreText = t('menu.slots.subtitle');
    else if (isSettings) loreText = t('menu.settings.subtitle');
    else if (isExitConfirm) loreText = t('menu.exit.desc');

    const header = el(
      'header',
      { class: 'menu-header' },
      el(
        'div',
        { class: 'menu-top-line' },
        el(
          'div',
          { class: 'menu-signal-line' },
          el('span', { class: 'signal-dot' }),
          el('span', { class: 'menu-signal-label' }, signalLabel),
        ),
        localeBtn,
      ),
      el('h1', { class: 'menu-title' }, t('app.title')),
      el('p', { class: 'menu-lore' }, loreText),
    );

    let frame;

    if (isCreate) {
      const stepTabs = [
        { step: 1, key: 'character.steps.identity', glyph: '🆔' },
        { step: 2, key: 'character.steps.archetype', glyph: '🎒' },
        { step: 3, key: 'character.steps.sector', glyph: '📍' },
        { step: 4, key: 'character.steps.summary', glyph: '📋' },
      ].map(({ step, key, glyph }) => {
        const isActive = this.#currentStep === step;
        return el(
          'button',
          {
            type: 'button',
            class: ['menu-stepper-tab', isActive && 'is-active'],
            onClick: () => {
              this.#currentStep = step;
              this.render();
            },
          },
          el('span', { class: 'stepper-tab-glyph' }, glyph),
          el('span', { class: 'stepper-tab-label' }, t(key)),
        );
      });

      const stepperBar = el('div', { class: 'menu-stepper-bar' }, stepTabs);
      const stepBody = this.#renderActiveStep();
      const navBar = this.#renderStepNavBar();

      frame = el(
        'div',
        { class: 'menu-frame' },
        header,
        stepperBar,
        el('div', { class: 'menu-body' }, stepBody),
        navBar,
      );
    } else if (isLoadGame) {
      frame = el(
        'div',
        { class: 'menu-frame' },
        header,
        el('div', { class: 'menu-body' }, this.#renderLoadGameScreen()),
      );
    } else if (isSettings) {
      frame = el(
        'div',
        { class: 'menu-frame' },
        header,
        el('div', { class: 'menu-body' }, this.#renderSettingsScreen()),
      );
    } else if (isExitConfirm) {
      frame = el(
        'div',
        { class: 'menu-frame' },
        header,
        el('div', { class: 'menu-body' }, this.#renderExitConfirmScreen()),
      );
    } else if (isTerminated) {
      frame = el(
        'div',
        { class: 'menu-frame is-terminated' },
        header,
        el('div', { class: 'menu-body' }, this.#renderTerminatedScreen()),
      );
    } else {
      // Main Menu ('menu')
      const bodyContent = this.#renderMainMenuScreen();
      frame = el(
        'div',
        { class: 'menu-frame' },
        header,
        el('div', { class: 'menu-body' }, bodyContent),
        el(
          'footer',
          { class: 'menu-footer' },
          el('span', { class: 'menu-footer-sub' }, t('app.subtitle')),
          el('span', { class: 'menu-footer-hint' }, t('menu.footer_hint')),
        ),
      );
    }

    // Modal overlay if premium modal is open
    if (this.#isPremiumModalOpen) {
      const modal = this.#renderPremiumModal();
      frame.appendChild(modal);
    }

    this.#root.replaceChildren(frame);
    this.#lastRenderedMode = this.#mode;
    this.#lastRenderedStep = this.#currentStep;

    if (isSameStepAndMode && prevScrollTop > 0) {
      const newBody = this.#root.querySelector('.menu-body');
      if (newBody) {
        newBody.scrollTop = prevScrollTop;
      }
    }
  }

  // =========================================================================
  // 1. MAIN MENU SCREEN (NEW GAME, LOAD GAME, SETTINGS, EXIT + ACTIVE CONTINUE)
  // =========================================================================
  #renderMainMenuScreen() {
    const sections = [];

    // If an active expedition is ongoing, offer prominent Continue option
    if (this.#hasSave && this.#savedState) {
      const continueSection = this.#renderContinueCard(this.#savedState);
      sections.push(continueSection);
    }

    // Main 4 Core Menu Buttons
    const menuActions = [
      {
        id: 'new_game',
        glyph: '✦',
        titleKey: 'menu.action.new_game_main',
        descKey: 'menu.action.desc_new_game',
        isAccent: true,
        onClick: () => {
          this.#mode = 'create';
          this.#currentStep = 1;
          this.render();
        },
      },
      {
        id: 'load_game',
        glyph: '💾',
        titleKey: 'menu.action.load_game',
        descKey: 'menu.action.desc_load_game',
        isAccent: false,
        onClick: () => {
          this.#mode = 'load_game';
          this.render();
        },
      },
      {
        id: 'codex',
        glyph: '📖',
        titleKey: 'menu.action.codex_memorial',
        descKey: 'menu.action.desc_codex_memorial',
        isAccent: false,
        onClick: () => {
          if (this.#onOpenCodex) this.#onOpenCodex();
        },
      },
      {
        id: 'settings',
        glyph: '⚙',
        titleKey: 'menu.action.settings',
        descKey: 'menu.action.desc_settings',
        isAccent: false,
        onClick: () => {
          this.#mode = 'settings';
          this.render();
        },
      },
      {
        id: 'exit',
        glyph: '⏻',
        titleKey: 'menu.action.exit',
        descKey: 'menu.action.desc_exit',
        isAccent: false,
        onClick: () => {
          this.#mode = 'exit_confirm';
          this.render();
        },
      },
    ];

    if (this.#pwaManager && !this.#pwaManager.isInstalled) {
      menuActions.push({
        id: 'install_app',
        glyph: '📲',
        titleKey: 'menu.action.install_app',
        descKey: 'menu.action.desc_install_app',
        isAccent: false,
        onClick: () => {
          this.#pwaManager.install();
        },
      });
    }

    const actionCards = menuActions.map((action) => {
      return el(
        'button',
        {
          type: 'button',
          class: ['menu-action-card', action.isAccent && 'is-accent-action'],
          onClick: action.onClick,
        },
        el('span', { class: 'menu-action-glyph' }, action.glyph),
        el(
          'div',
          { class: 'menu-action-content' },
          el('strong', { class: 'menu-action-title' }, t(action.titleKey)),
          el('span', { class: 'menu-action-desc' }, t(action.descKey)),
        ),
        el('span', { class: 'menu-action-arrow' }, '→'),
      );
    });

    const menuGrid = el(
      'section',
      { class: 'menu-section menu-main-nav-section' },
      el('div', { class: 'menu-action-list' }, actionCards),
    );

    sections.push(menuGrid);
    return sections;
  }

  #renderContinueCard(state) {
    const { day } = readClock(state.time.minutes);
    const clock = formatClock(state.time.minutes);
    const location = t(`location.${state.world.currentNodeId}`);
    const hp = Math.round(state.player.health);
    const charted = Object.values(state.world.nodes).filter((n) => n.visited).length;
    const name = state.player?.name || t('character.default_name');
    const archetypeKey = state.player?.archetype || 'scavenger';

    return el(
      'section',
      { class: 'menu-section menu-continue-card' },
      el(
        'div',
        { class: 'menu-continue-info' },
        el(
          'div',
          { class: 'menu-continue-header-line' },
          el('span', { class: 'meta-label' }, t('menu.active_transmission')),
          el('span', { class: 'menu-continue-tag' }, `${name.toUpperCase()} // ${t(`menu.archetype.${archetypeKey}.name`)}`),
        ),
        el('h2', { class: 'menu-continue-title' }, `${location} — ${t('hud.day', { day })} · ${clock}`),
        el(
          'div',
          { class: 'route-meta menu-continue-stats' },
          el('span', {}, `${t('status.vital.health')}: ${hp}%`),
          el('span', {}, `·`),
          el('span', {}, `${t('menu.charted_sectors', { count: charted })}`),
        ),
      ),
      el(
        'button',
        {
          type: 'button',
          class: 'btn btn-accent menu-cta-btn',
          onClick: () => this.#onContinue(),
        },
        t('menu.action.continue'),
      ),
    );
  }

  // =========================================================================
  // 2. LOAD GAME SCREEN (10 SLOTS: 2 FREE, 8 PREMIUM)
  // =========================================================================
  #renderLoadGameScreen() {
    const isPremium = this.#saveManager ? this.#saveManager.isPremium() : false;
    const slots = this.#saveManager ? this.#saveManager.listSlots() : [];

    const backBtn = el(
      'button',
      {
        type: 'button',
        class: 'btn btn-ghost menu-back-nav-btn',
        onClick: () => {
          this.#mode = 'menu';
          this.render();
        },
      },
      t('menu.action.back_to_menu'),
    );

    const premiumStatusPill = el(
      'div',
      { class: 'menu-premium-status-bar' },
      el(
        'span',
        { class: ['slot-tier-badge', isPremium ? 'is-tier-premium' : 'is-tier-free'] },
        isPremium ? t('menu.slots.premium_status_active') : t('menu.slots.premium_status_free'),
      ),
      el(
        'button',
        {
          type: 'button',
          class: 'btn btn-ghost btn-sm menu-premium-toggle-btn',
          onClick: () => {
            this.#isPremiumModalOpen = true;
            this.render();
          },
        },
        isPremium ? '👑 Premium Bilgisi / Test' : `👑 ${t('menu.slots.upgrade_cta')}`,
      ),
    );

    const topBar = el('div', { class: 'menu-slots-top-bar' }, backBtn, premiumStatusPill);

    const slotCards = slots.map((slotData) => {
      const { slot, isPremiumSlot, isLocked, hasSave, meta, isActive } = slotData;

      if (isLocked) {
        // Locked Premium Slot (Slots 3-10 without premium)
        return el(
          'div',
          { class: 'slot-card is-premium-locked' },
          el(
            'div',
            { class: 'slot-card-header' },
            el('span', { class: 'slot-index-badge' }, `SLOT ${slot}`),
            el('span', { class: 'slot-tier-badge is-tier-locked' }, t('menu.slots.locked_badge')),
          ),
          el(
            'div',
            { class: 'slot-locked-content' },
            el('span', { class: 'slot-lock-icon' }, '🔒'),
            el('strong', { class: 'slot-locked-title' }, `YUVA ${slot} // ${t('menu.slots.premium_badge')}`),
            el('p', { class: 'slot-locked-desc' }, t('menu.slots.locked_desc')),
          ),
          el(
            'div',
            { class: 'slot-card-actions' },
            el(
              'button',
              {
                type: 'button',
                class: 'btn btn-accent btn-sm slot-unlock-btn',
                onClick: () => {
                  this.#isPremiumModalOpen = true;
                  this.render();
                },
              },
              t('menu.slots.unlock_btn'),
            ),
          ),
        );
      }

      // Unlocked slot (Free slot 1-2, or 3-10 with premium)
      if (hasSave && meta) {
        const { day } = readClock(meta.minutes);
        const clock = formatClock(meta.minutes);
        const locName = t(`location.${meta.locationId}`);
        const dateStr = new Date(meta.savedAt).toLocaleDateString(undefined, {
          month: 'short',
          day: 'numeric',
          hour: '2-digit',
          minute: '2-digit',
        });

        return el(
          'div',
          { class: ['slot-card is-unlocked', isActive && 'is-active-slot'] },
          el(
            'div',
            { class: 'slot-card-header' },
            el('span', { class: 'slot-index-badge' }, `SLOT ${slot}`),
            el(
              'span',
              { class: ['slot-tier-badge', isPremiumSlot ? 'is-tier-premium' : 'is-tier-free'] },
              isPremiumSlot ? t('menu.slots.premium_badge') : t('menu.slots.free_badge'),
            ),
            isActive && el('span', { class: 'slot-active-pill' }, t('menu.slots.active_badge')),
          ),
          el(
            'div',
            { class: 'slot-save-info' },
            el(
              'div',
              { class: 'slot-survivor-callsign' },
              el('strong', {}, (meta.name || t('character.default_name')).toUpperCase()),
              el('span', { class: 'slot-archetype-label' }, `// ${t(`menu.archetype.${meta.archetype}.name`)}`),
            ),
            el('div', { class: 'slot-meta-line' }, `${locName} — ${t('hud.day', { day })} · ${clock}`),
            el(
              'div',
              { class: 'slot-vitals-line' },
              el('span', {}, `${t('status.vital.health')}: ${meta.health}%`),
              el('span', {}, `·`),
              el('span', { class: 'slot-timestamp' }, `📅 ${dateStr}`),
            ),
          ),
          el(
            'div',
            { class: 'slot-card-actions' },
            el(
              'button',
              {
                type: 'button',
                class: 'btn btn-accent btn-sm',
                onClick: () => {
                  if (this.#onLoadSlot) {
                    this.#onLoadSlot(slot);
                  }
                },
              },
              t('menu.slots.load_btn'),
            ),
            this.#savedState &&
              el(
                'button',
                {
                  type: 'button',
                  class: 'btn btn-ghost btn-sm',
                  onClick: () => {
                    if (this.#onSaveSlot) {
                      this.#onSaveSlot(slot);
                      this.render();
                    }
                  },
                },
                t('menu.slots.save_btn'),
              ),
            el(
              'button',
              {
                type: 'button',
                class: 'btn btn-ghost btn-sm slot-delete-btn',
                onClick: () => {
                  if (window.confirm(t('menu.slots.delete_confirm'))) {
                    if (this.#onDeleteSlot) {
                      this.#onDeleteSlot(slot);
                      this.render();
                    }
                  }
                },
              },
              t('menu.slots.delete_btn'),
            ),
          ),
        );
      }

      // Empty unlocked slot
      return el(
        'div',
        { class: 'slot-card is-empty-slot' },
        el(
          'div',
          { class: 'slot-card-header' },
          el('span', { class: 'slot-index-badge' }, `SLOT ${slot}`),
          el(
            'span',
            { class: ['slot-tier-badge', isPremiumSlot ? 'is-tier-premium' : 'is-tier-free'] },
            isPremiumSlot ? t('menu.slots.premium_badge') : t('menu.slots.free_badge'),
          ),
        ),
        el(
          'div',
          { class: 'slot-empty-content' },
          el('strong', { class: 'slot-empty-title' }, t('menu.slots.empty')),
          el('p', { class: 'slot-empty-desc' }, t('menu.slots.empty_desc')),
        ),
        el(
          'div',
          { class: 'slot-card-actions' },
          this.#savedState &&
            el(
              'button',
              {
                type: 'button',
                class: 'btn btn-accent btn-sm',
                onClick: () => {
                  if (this.#onSaveSlot) {
                    this.#onSaveSlot(slot);
                    this.render();
                  }
                },
              },
              t('menu.slots.save_btn'),
            ),
          el(
            'button',
            {
              type: 'button',
              class: 'btn btn-ghost btn-sm',
              onClick: () => {
                if (this.#saveManager) {
                  this.#saveManager.setActiveSlot(slot);
                }
                this.#mode = 'create';
                this.#currentStep = 1;
                this.render();
              },
            },
            t('menu.action.new_game_main'),
          ),
        ),
      );
    });

    return [
      topBar,
      el('div', { class: 'menu-slots-grid' }, slotCards),
    ];
  }

  // =========================================================================
  // 3. PREMIUM UNLOCK MODAL
  // =========================================================================
  #renderPremiumModal() {
    const isPremium = this.#saveManager ? this.#saveManager.isPremium() : false;

    const featureItems = [
      t('menu.premium.feature_1'),
      t('menu.premium.feature_2'),
      t('menu.premium.feature_3'),
      t('menu.premium.feature_4'),
    ].map((f) => el('li', { class: 'premium-feature-item' }, el('span', { class: 'premium-bullet' }, '✦'), el('span', {}, f)));

    let promoInputEl;
    let promoFeedbackEl = el('span', { class: 'promo-feedback-msg' }, '');

    const promoBox = !isPremium
      ? el(
          'div',
          { class: 'promo-code-container' },
          el('span', { class: 'promo-code-label' }, t('menu.premium.promo_label')),
          el(
            'div',
            { class: 'promo-code-row' },
            (promoInputEl = el('input', {
              type: 'text',
              class: 'promo-code-input',
              placeholder: 'Örn: VIP-SURVIVOR',
              maxLength: 30,
            })),
            el(
              'button',
              {
                type: 'button',
                class: 'btn btn-sm btn-accent',
                onClick: () => {
                  const val = promoInputEl?.value?.trim();
                  const res = adManager.redeemPromoCode(val);
                  if (res.ok) {
                    promoFeedbackEl.textContent = t('menu.premium.promo_success');
                    promoFeedbackEl.className = 'promo-feedback-msg tone-good';
                    setTimeout(() => {
                      this.render();
                    }, 600);
                  } else {
                    promoFeedbackEl.textContent = t('menu.premium.promo_invalid');
                    promoFeedbackEl.className = 'promo-feedback-msg tone-warn';
                  }
                },
              },
              t('menu.premium.promo_submit'),
            ),
          ),
          promoFeedbackEl,
        )
      : null;

    return el(
      'div',
      { class: 'premium-modal-backdrop' },
      el(
        'div',
        { class: 'premium-modal-dialog' },
        el(
          'header',
          { class: 'premium-modal-header' },
          el('span', { class: 'premium-kicker' }, t('menu.premium.kicker')),
          el('h2', { class: 'premium-title' }, `👑 ${t('menu.premium.title')}`),
          el('p', { class: 'premium-desc' }, isPremium ? t('menu.premium.active_badge') : t('menu.premium.desc')),
        ),
        el('ul', { class: 'premium-feature-list' }, featureItems),
        promoBox,
        el(
          'div',
          { class: 'premium-modal-actions' },
          !isPremium
            ? el(
                'button',
                {
                  type: 'button',
                  class: 'btn btn-accent premium-cta-btn',
                  onClick: () => {
                    if (this.#saveManager) {
                      this.#saveManager.setPremium(true);
                    }
                    this.render();
                  },
                },
                t('menu.premium.unlock_btn'),
              )
            : el(
                'button',
                {
                  type: 'button',
                  class: 'btn btn-ghost premium-revoke-btn',
                  onClick: () => {
                    if (this.#saveManager) {
                      this.#saveManager.setPremium(false);
                    }
                    this.render();
                  },
                },
                t('menu.premium.revoke_btn'),
              ),
          el(
            'button',
            {
              type: 'button',
              class: 'btn btn-ghost',
              onClick: () => {
                this.#isPremiumModalOpen = false;
                this.render();
              },
            },
            t('menu.premium.close'),
          ),
        ),
      ),
    );
  }

  // =========================================================================
  // 4. SETTINGS SCREEN
  // =========================================================================
  #renderSettingsScreen() {
    const backBtn = el(
      'button',
      {
        type: 'button',
        class: 'btn btn-ghost menu-back-nav-btn',
        onClick: () => {
          this.#mode = 'menu';
          this.render();
        },
      },
      t('menu.action.back_to_menu'),
    );

    // Language options
    const isTr = i18n.locale === 'tr';
    const langGroup = el(
      'div',
      { class: 'settings-row' },
      el('label', { class: 'settings-label' }, t('menu.settings.language')),
      el(
        'div',
        { class: 'settings-btn-group' },
        el(
          'button',
          {
            type: 'button',
            class: ['btn btn-sm', isTr ? 'btn-accent' : 'btn-ghost'],
            onClick: () => this.#onLocaleChange('tr'),
          },
          'Türkçe (TR)',
        ),
        el(
          'button',
          {
            type: 'button',
            class: ['btn btn-sm', !isTr ? 'btn-accent' : 'btn-ghost'],
            onClick: () => this.#onLocaleChange('en'),
          },
          'English (EN)',
        ),
      ),
    );

    // Audio SFX Volume Slider
    const initialSfx = localStorage.getItem('lastbreath.sfx_volume') || '80';
    const sfxBadge = el('span', { class: 'settings-val-badge' }, `${initialSfx}%`);
    const sfxSlider = el('input', {
      type: 'range',
      min: '0',
      max: '100',
      value: initialSfx,
      class: 'menu-range-slider',
      onInput: (e) => {
        const val = e.target.value;
        sfxBadge.textContent = `${val}%`;
        localStorage.setItem('lastbreath.sfx_volume', val);
      },
    });

    const sfxRow = el(
      'div',
      { class: 'settings-row' },
      el('div', { class: 'settings-spread' }, el('label', { class: 'settings-label' }, t('menu.settings.sfx')), sfxBadge),
      sfxSlider,
    );

    // Ambient / Music Volume Slider
    const initialAmb = localStorage.getItem('lastbreath.ambient_volume') || '60';
    const ambBadge = el('span', { class: 'settings-val-badge' }, `${initialAmb}%`);
    const ambSlider = el('input', {
      type: 'range',
      min: '0',
      max: '100',
      value: initialAmb,
      class: 'menu-range-slider',
      onInput: (e) => {
        const val = e.target.value;
        ambBadge.textContent = `${val}%`;
        localStorage.setItem('lastbreath.ambient_volume', val);
      },
    });

    const ambRow = el(
      'div',
      { class: 'settings-row' },
      el('div', { class: 'settings-spread' }, el('label', { class: 'settings-label' }, t('menu.settings.ambient')), ambBadge),
      ambSlider,
    );

    // CRT Scanlines Effect Toggle
    const isCrt = localStorage.getItem('lastbreath.crt_effects') !== 'false';
    const crtBtn = el(
      'button',
      {
        type: 'button',
        class: ['btn btn-sm', isCrt ? 'btn-accent' : 'btn-ghost'],
        onClick: () => {
          const nextVal = !isCrt;
          localStorage.setItem('lastbreath.crt_effects', String(nextVal));
          document.body.classList.toggle('crt-active', nextVal);
          this.render();
        },
      },
      isCrt ? t('menu.settings.on') : t('menu.settings.off'),
    );

    const crtRow = el(
      'div',
      { class: 'settings-row settings-inline-row' },
      el('label', { class: 'settings-label' }, t('menu.settings.crt')),
      crtBtn,
    );

    // Auto-Save Toggle
    const isAutosave = localStorage.getItem('lastbreath.autosave') !== 'false';
    const autosaveBtn = el(
      'button',
      {
        type: 'button',
        class: ['btn btn-sm', isAutosave ? 'btn-accent' : 'btn-ghost'],
        onClick: () => {
          const nextVal = !isAutosave;
          localStorage.setItem('lastbreath.autosave', String(nextVal));
          this.render();
        },
      },
      isAutosave ? t('menu.settings.on') : t('menu.settings.off'),
    );

    const autosaveRow = el(
      'div',
      { class: 'settings-row settings-inline-row' },
      el('label', { class: 'settings-label' }, t('menu.settings.autosave')),
      autosaveBtn,
    );

    // Danger Zone / Clear All Data
    const dangerZone = el(
      'div',
      { class: 'settings-danger-card' },
      el('strong', { class: 'settings-danger-title' }, t('menu.settings.reset_title')),
      el('p', { class: 'settings-danger-desc' }, t('menu.settings.reset_desc')),
      el(
        'button',
        {
          type: 'button',
          class: 'btn btn-ghost slot-delete-btn',
          onClick: () => {
            if (window.confirm(t('menu.settings.reset_confirm'))) {
              if (this.#onResetAll) {
                this.#onResetAll();
              }
              this.#mode = 'menu';
              this.render();
            }
          },
        },
        t('menu.settings.reset_btn'),
      ),
    );

    // PWA Mobile / Desktop Install Row
    const pwaRow = el(
      'div',
      { class: 'settings-row settings-inline-row' },
      el(
        'div',
        { class: 'settings-label-col' },
        el('label', { class: 'settings-label' }, t('menu.action.install_app')),
        el('span', { class: 'settings-sub-note' }, t('menu.action.desc_install_app')),
      ),
      el(
        'button',
        {
          type: 'button',
          class: 'btn btn-sm btn-accent',
          onClick: () => {
            if (this.#pwaManager) {
              this.#pwaManager.install();
            }
          },
        },
        '📲 ' + t('hud.install_app'),
      ),
    );

    const settingsContainer = el(
      'section',
      { class: 'menu-section menu-settings-section' },
      langGroup,
      pwaRow,
      sfxRow,
      ambRow,
      crtRow,
      autosaveRow,
      dangerZone,
    );

    return [backBtn, settingsContainer];
  }

  // =========================================================================
  // 5. EXIT & TERMINATED SCREENS
  // =========================================================================
  #renderExitConfirmScreen() {
    return el(
      'section',
      { class: 'menu-section menu-exit-section' },
      el('h2', { class: 'menu-exit-title' }, `⏻ ${t('menu.exit.title')}`),
      el('p', { class: 'menu-exit-desc' }, t('menu.exit.desc')),
      el(
        'div',
        { class: 'menu-exit-actions' },
        el(
          'button',
          {
            type: 'button',
            class: 'btn btn-accent menu-exit-confirm-btn',
            onClick: () => {
              if (this.#saveManager) {
                this.#saveManager.save();
              }
              this.#mode = 'terminated';
              this.render();
            },
          },
          t('menu.exit.confirm_btn'),
        ),
        el(
          'button',
          {
            type: 'button',
            class: 'btn btn-ghost',
            onClick: () => {
              this.#mode = 'menu';
              this.render();
            },
          },
          t('menu.exit.cancel_btn'),
        ),
      ),
    );
  }

  #renderTerminatedScreen() {
    return el(
      'section',
      { class: 'menu-section menu-terminated-card' },
      el('div', { class: 'terminal-static-line' }, '/// NO CARRIER — LINK DROPPED ///'),
      el('h2', { class: 'terminated-title' }, t('menu.exit.terminated_title')),
      el('p', { class: 'terminated-desc' }, t('menu.exit.terminated_desc')),
      el(
        'button',
        {
          type: 'button',
          class: 'btn btn-accent menu-reconnect-btn',
          onClick: () => {
            this.#mode = 'menu';
            this.render();
          },
        },
        t('menu.exit.reconnect_btn'),
      ),
    );
  }

  // =========================================================================
  // 6. CHARACTER CREATION STEPS
  // =========================================================================
  #renderActiveStep() {
    switch (this.#currentStep) {
      case 1:
        return this.#renderStepIdentity();
      case 2:
        return this.#renderStepArchetype();
      case 3:
        return this.#renderStepSector();
      case 4:
      default:
        return this.#renderStepSummary();
    }
  }

  #renderStepIdentity() {
    const nameInput = el('input', {
      type: 'text',
      class: 'menu-text-input',
      maxlength: '24',
      value: this.#name,
      placeholder: t('character.placeholder.name'),
      onInput: (e) => {
        this.#name = e.target.value;
      },
    });

    const randomNameBtn = el(
      'button',
      {
        type: 'button',
        class: 'btn btn-ghost menu-random-btn',
        onClick: () => {
          this.#name = getRandomName(this.#name);
          nameInput.value = this.#name;
        },
      },
      t('character.action.random_name'),
    );

    const ageBracket = getAgeBracket(this.#age);
    const ageValueBadge = el('strong', { class: 'menu-badge-val' }, `${this.#age}`);
    const ageBracketDesc = el('span', { class: 'menu-sub-note' }, t(`character.age_bracket.${ageBracket}`));

    const ageSlider = el('input', {
      type: 'range',
      class: 'menu-range-slider',
      min: '18',
      max: '65',
      value: String(this.#age),
      onInput: (e) => {
        this.#age = Number(e.target.value);
        ageValueBadge.textContent = `${this.#age}`;
        const nextBracket = getAgeBracket(this.#age);
        ageBracketDesc.textContent = t(`character.age_bracket.${nextBracket}`);
      },
    });

    const bloodChips = BLOOD_TYPES.map((type) => {
      const isSelected = this.#bloodType === type;
      return el(
        'button',
        {
          type: 'button',
          class: ['menu-blood-chip', isSelected && 'is-selected'],
          onClick: (e) => {
            this.#bloodType = type;
            const grid = e.currentTarget.closest('.menu-blood-grid');
            if (grid) {
              grid.querySelectorAll('.menu-blood-chip').forEach((chip) => {
                chip.classList.remove('is-selected');
              });
              e.currentTarget.classList.add('is-selected');
            } else {
              this.render();
            }
          },
        },
        type,
      );
    });

    const traitCards = Object.entries(TRAITS).map(([id, def]) => {
      const isSelected = this.#selectedTrait === id;
      return el(
        'button',
        {
          type: 'button',
          class: ['menu-trait-card', isSelected && 'is-selected'],
          onClick: (e) => {
            this.#selectedTrait = id;
            const grid = e.currentTarget.closest('.menu-trait-grid');
            if (grid) {
              grid.querySelectorAll('.menu-trait-card').forEach((card) => {
                card.classList.remove('is-selected');
                const badge = card.querySelector('.menu-check-badge');
                if (badge) badge.remove();
              });
              e.currentTarget.classList.add('is-selected');
              const head = e.currentTarget.querySelector('.menu-option-head');
              if (head && !head.querySelector('.menu-check-badge')) {
                head.appendChild(el('span', { class: 'menu-check-badge' }, '✓'));
              }
            } else {
              this.render();
            }
          },
        },
        el(
          'div',
          { class: 'menu-option-head' },
          el('span', { class: 'item-glyph' }, def.glyph),
          el('strong', { class: 'menu-option-name' }, t(`trait.${id}.name`)),
          isSelected && el('span', { class: 'menu-check-badge' }, '✓'),
        ),
        el('p', { class: 'menu-option-desc' }, t(`trait.${id}.desc`)),
      );
    });

    return el(
      'section',
      { class: 'menu-section menu-step-section' },
      el('h2', { class: 'block-title' }, t('character.label.identity')),
      el(
        'div',
        { class: 'menu-form-row' },
        el(
          'div',
          { class: 'menu-form-col' },
          el('label', { class: 'meta-label' }, t('character.label.name')),
          el('div', { class: 'menu-input-cluster' }, nameInput, randomNameBtn),
        ),
        el(
          'div',
          { class: 'menu-form-col' },
          el(
            'div',
            { class: 'menu-label-spread' },
            el('label', { class: 'meta-label' }, t('character.label.age')),
            ageValueBadge,
          ),
          ageSlider,
          ageBracketDesc,
        ),
      ),
      el('div', { class: 'menu-label-row' }, el('label', { class: 'meta-label' }, t('character.label.blood'))),
      el('div', { class: 'menu-blood-grid' }, bloodChips),
      el('div', { class: 'menu-label-row' }, el('label', { class: 'meta-label' }, t('character.label.trait'))),
      el('div', { class: 'menu-trait-grid' }, traitCards),
    );
  }

  #renderStepArchetype() {
    const archetypeCards = Object.entries(ARCHETYPES).map(([id, def]) => {
      const isSelected = this.#selectedArchetype === id;
      const itemLabels = def.kit
        .map(({ itemId, qty }) => `${t(`item.${itemId}.name`)}${qty > 1 ? ` ×${qty}` : ''}`)
        .join(' · ');

      return el(
        'button',
        {
          type: 'button',
          class: ['menu-option-card', isSelected && 'is-selected'],
          onClick: (e) => {
            this.#selectedArchetype = id;
            const grid = e.currentTarget.closest('.menu-archetype-grid');
            if (grid) {
              grid.querySelectorAll('.menu-option-card').forEach((card) => {
                card.classList.remove('is-selected');
                const badge = card.querySelector('.menu-check-badge');
                if (badge) badge.remove();
              });
              e.currentTarget.classList.add('is-selected');
              const head = e.currentTarget.querySelector('.menu-option-head');
              if (head && !head.querySelector('.menu-check-badge')) {
                head.appendChild(el('span', { class: 'menu-check-badge' }, '✓'));
              }
            } else {
              this.render();
            }
          },
        },
        el(
          'div',
          { class: 'menu-option-head' },
          el('span', { class: 'item-glyph' }, def.glyph),
          el('strong', { class: 'menu-option-name' }, t(`menu.archetype.${id}.name`)),
          isSelected && el('span', { class: 'menu-check-badge' }, '✓'),
        ),
        el('p', { class: 'menu-option-desc' }, t(`menu.archetype.${id}.desc`)),
        el('span', { class: 'menu-option-kit' }, `📦 ${itemLabels}`),
      );
    });

    return el(
      'section',
      { class: 'menu-section menu-step-section' },
      el('h2', { class: 'block-title' }, t('character.label.archetype')),
      el('div', { class: 'menu-archetype-grid' }, archetypeCards),
    );
  }

  #renderStepSector() {
    const locationChips = STARTING_LOCATIONS.map((nodeId) => {
      const node = getNode(nodeId);
      const isSelected = this.#selectedLocation === nodeId;
      return el(
        'button',
        {
          type: 'button',
          class: ['menu-sector-chip', isSelected && 'is-selected'],
          onClick: (e) => {
            this.#selectedLocation = nodeId;
            const grid = e.currentTarget.closest('.menu-sector-grid');
            if (grid) {
              grid.querySelectorAll('.menu-sector-chip').forEach((chip) => {
                chip.classList.remove('is-selected');
                const badge = chip.querySelector('.menu-check-badge');
                if (badge) badge.remove();
              });
              e.currentTarget.classList.add('is-selected');
              const top = e.currentTarget.querySelector('.sector-chip-top');
              if (top && !top.querySelector('.menu-check-badge')) {
                top.appendChild(el('span', { class: 'menu-check-badge' }, '✓'));
              }
            } else {
              this.render();
            }
          },
        },
        el(
          'div',
          { class: 'sector-chip-top' },
          el('span', { class: 'sector-chip-name' }, t(`location.${nodeId}`)),
          isSelected && el('span', { class: 'menu-check-badge' }, '✓'),
        ),
        el(
          'span',
          { class: 'sector-chip-meta' },
          `${t(`biome.${node.biome}`)} · ${'▲'.repeat(node.danger)}`,
        ),
      );
    });

    return el(
      'section',
      { class: 'menu-section menu-step-section' },
      el('h2', { class: 'block-title' }, t('character.label.sector')),
      el('div', { class: 'menu-sector-grid' }, locationChips),
    );
  }

  #renderStepSummary() {
    const finalName = (this.#name.trim() || t('character.default_name')).toUpperCase();
    const archetype = ARCHETYPES[this.#selectedArchetype] || ARCHETYPES.scavenger;
    const node = getNode(this.#selectedLocation);

    const kitSummary = archetype.kit
      .map(({ itemId, qty }) => `${t(`item.${itemId}.name`)}${qty > 1 ? ` ×${qty}` : ''}`)
      .join(', ');

    const dossierCard = el(
      'div',
      { class: 'menu-live-dossier' },
      el(
        'div',
        { class: 'live-dossier-header' },
        el('span', { class: 'live-dossier-kicker' }, t('character.label.dossier_preview')),
        el(
          'strong',
          { class: 'live-dossier-callsign' },
          `${finalName} // ${t(`menu.archetype.${this.#selectedArchetype}.name`)}`,
        ),
      ),
      el(
        'div',
        { class: 'live-dossier-meta' },
        el('span', {}, `${t('character.label.age')}: ${this.#age}`),
        el('span', {}, `·`),
        el('span', {}, `${t('character.label.blood')}: ${this.#bloodType}`),
        el('span', {}, `·`),
        el('span', {}, `${t('character.label.trait')}: ${t(`trait.${this.#selectedTrait}.name`)}`),
        el('span', {}, `·`),
        el(
          'span',
          {},
          `${t('character.label.sector')}: ${t(`location.${this.#selectedLocation}`)} (${t(`biome.${node.biome}`)})`,
        ),
      ),
      el('div', { class: 'live-dossier-kit' }, `📦 ${t('character.label.archetype')}: ${kitSummary}`),
    );

    return el(
      'section',
      { class: 'menu-section menu-step-section' },
      el('h2', { class: 'block-title' }, t('character.label.dossier_preview')),
      dossierCard,
    );
  }

  #renderStepNavBar() {
    const isFirstStep = this.#currentStep === 1;
    const isLastStep = this.#currentStep === 4;

    const leftBtn = isFirstStep
      ? el(
          'button',
          {
            type: 'button',
            class: 'btn btn-ghost menu-nav-btn',
            onClick: () => {
              this.#mode = 'menu';
              this.render();
            },
          },
          t('character.action.back_to_menu'),
        )
      : el(
          'button',
          {
            type: 'button',
            class: 'btn btn-ghost menu-nav-btn',
            onClick: () => {
              this.#currentStep = Math.max(1, this.#currentStep - 1);
              this.render();
            },
          },
          t('character.action.prev'),
        );

    const rightBtn = isLastStep
      ? el(
          'button',
          {
            type: 'button',
            class: 'btn btn-accent menu-nav-btn menu-deploy-btn',
            onClick: () => {
              try {
                const finalName = this.#name.trim() || t('character.default_name');
                this.close();
                this.#onStartNew({
                  name: finalName,
                  age: this.#age,
                  bloodType: this.#bloodType,
                  trait: this.#selectedTrait,
                  archetypeId: this.#selectedArchetype,
                  locationId: this.#selectedLocation,
                });
              } catch (err) {
                console.error('[menuView] deploy button error:', err);
              }
            },
          },
          t('character.action.deploy'),
        )
      : el(
          'button',
          {
            type: 'button',
            class: 'btn btn-accent menu-nav-btn',
            onClick: () => {
              this.#currentStep = Math.min(4, this.#currentStep + 1);
              this.render();
            },
          },
          t('character.action.next'),
        );

    return el('div', { class: 'menu-step-nav-bar' }, leftBtn, rightBtn);
  }
}


  // --- src/ui/lootModalView.js ---






class LootModalView {
  #root;
  #engine;
  #current = null;
  #selectedMap = new Map(); // index -> boolean
  #isScanning = false;
  #scanProgress = 0;
  #revealedCount = 0;
  #scanTimer = null;
  #startTime = 0;
  #scanDuration = 2400;

  // Cached DOM elements for stable, shake-free updates
  #cardEl = null;
  #statusTitleEl = null;
  #counterDigitalEl = null;
  #progressFillEl = null;
  #telemetryEl = null;
  #speedupBtnEl = null;
  #itemsListEl = null;
  #placeholderEl = null;
  #capacityLabelEl = null;
  #capacityBarEl = null;
  #footerEl = null;
  #itemRowEls = [];

  constructor(root, engine) {
    this.#root = root;
    this.#engine = engine;
  }

  get isOpen() {
    return !this.#root.hidden;
  }

  open({ type, titleKey, descKey, descParams = {}, items = [], nodeId, onConfirm }) {
    this.#clearScanTimer();
    this.#current = {
      type,
      titleKey,
      descKey,
      descParams,
      items,
      nodeId,
      onConfirm,
    };
    this.#selectedMap.clear();
    items.forEach((_, idx) => this.#selectedMap.set(idx, true));

    const isScavenge = type === 'scavenge' || type === 'scavenge_empty';
    if (isScavenge) {
      this.#isScanning = true;
      this.#scanProgress = 0;
      this.#revealedCount = 0;
      this.#scanDuration = items.length > 0 ? 2500 : 1600;
      this.#startTime = Date.now();
      this.#root.hidden = false;
      this.#buildInitialCard();
      this.#startScan(items);
    } else {
      this.#isScanning = false;
      this.#scanProgress = 100;
      this.#revealedCount = items.length;
      this.#root.hidden = false;
      this.#buildInitialCard();
    }
  }

  close() {
    this.#clearScanTimer();
    this.#root.hidden = true;
    this.#current = null;
    this.#selectedMap.clear();
    this.#isScanning = false;
    this.#scanProgress = 0;
    this.#revealedCount = 0;
    this.#cardEl = null;
    this.#itemRowEls = [];
  }

  #clearScanTimer() {
    if (this.#scanTimer) {
      clearInterval(this.#scanTimer);
      this.#scanTimer = null;
    }
  }

  #startScan(items) {
    this.#clearScanTimer();
    const count = items.length;

    this.#scanTimer = setInterval(() => {
      if (!this.#current || this.#root.hidden) {
        this.#clearScanTimer();
        return;
      }
      const elapsed = Date.now() - this.#startTime;
      const progress = Math.min(100, Math.floor((elapsed / this.#scanDuration) * 100));
      this.#scanProgress = progress;

      // In-place dynamic updates without re-creating card DOM
      if (this.#progressFillEl) {
        this.#progressFillEl.style.width = `${progress}%`;
      }
      if (this.#counterDigitalEl) {
        this.#counterDigitalEl.textContent = `%${progress}`;
      }

      if (count > 0) {
        for (let i = this.#revealedCount; i < count; i++) {
          const threshold = count === 1 ? 38 : Math.round(18 + (i / count) * 68);
          if (progress >= threshold) {
            this.#revealNextItem(i, items[i]);
            this.#revealedCount = i + 1;
            try {
              audioEngine.playGearRustle?.(0.35);
              audioEngine.playTerminalClick?.(1.1 + (i % 4) * 0.12, 0.4);
            } catch {}
          }
        }
      }

      if (progress >= 100) {
        this.#finishScan(items);
      }
    }, 45);
  }

  #revealNextItem(idx, item) {
    if (this.#placeholderEl && this.#placeholderEl.isConnected) {
      this.#placeholderEl.remove();
    }

    if (this.#telemetryEl && this.#current) {
      this.#telemetryEl.textContent = t('loot.scanner.items_detected', {
        revealed: idx + 1,
        total: this.#current.items.length,
      });
    }

    const row = this.#createItemRow(item, idx, true);
    this.#itemRowEls[idx] = row;
    this.#itemsListEl?.appendChild(row);
    this.#updateCapacityUI();
  }

  #finishScan(items) {
    this.#clearScanTimer();
    this.#isScanning = false;
    this.#scanProgress = 100;

    // Reveal any remaining items that didn't pop in yet
    for (let i = this.#revealedCount; i < items.length; i++) {
      this.#revealNextItem(i, items[i]);
    }
    this.#revealedCount = items.length;

    if (this.#placeholderEl && this.#placeholderEl.isConnected) {
      this.#placeholderEl.remove();
    }

    if (this.#progressFillEl) {
      this.#progressFillEl.style.width = '100%';
      this.#progressFillEl.classList.add('is-complete');
    }
    if (this.#counterDigitalEl) {
      this.#counterDigitalEl.textContent = '✓ 100%';
      this.#counterDigitalEl.classList.add('is-done');
    }
    if (this.#statusTitleEl) {
      this.#statusTitleEl.textContent =
        items.length > 0 ? t('loot.scanner.completed') : t('loot.scanner.empty_status');
    }
    if (this.#telemetryEl) {
      this.#telemetryEl.textContent =
        items.length > 0
          ? t('loot.scanner.completed_desc', { count: items.length })
          : t('loot.scanner.empty_desc');
    }
    if (this.#speedupBtnEl) {
      this.#speedupBtnEl.style.display = 'none';
    }

    // Enable inputs on item rows
    this.#itemRowEls.forEach((rowEl) => {
      if (!rowEl) return;
      const cb = rowEl.querySelector('input[type="checkbox"]');
      if (cb) cb.disabled = false;
      const btn = rowEl.querySelector('button');
      if (btn) btn.disabled = false;
    });

    // Update footer with interactive action buttons
    this.#renderUnlockedFooter();
    this.#updateCapacityUI();

    try {
      if (items.length > 0) {
        audioEngine.playAchievementChime?.();
      } else {
        audioEngine.playWarningAlarm?.(320, 0.2, 0.35);
      }
    } catch {}
  }

  #finishScanImmediately() {
    if (!this.#current) return;
    this.#finishScan(this.#current.items || []);
  }

  #createItemRow(item, idx, isScanning) {
    const def = getItem(item.itemId);
    const isSelected = Boolean(this.#selectedMap.get(idx));
    const totalItemWeight = i18n.formatNumber(def.weight * item.qty, 2);

    const checkbox = el('input', {
      type: 'checkbox',
      class: 'loot-item-checkbox',
      checked: isSelected,
      disabled: isScanning,
      onChange: (e) => {
        if (this.#isScanning) return;
        this.#toggleSelect(idx, e.target.checked);
      },
    });

    const toggleBtn = el(
      'button',
      {
        type: 'button',
        class: ['btn', 'btn-xs', isSelected ? 'btn-accent' : 'btn-ghost'],
        disabled: isScanning,
      },
      isSelected ? '✓' : '−',
    );

    const row = el(
      'div',
      {
        class: ['loot-item-row', isSelected && 'is-selected', 'loot-item-revealed-anim'],
        onClick: () => {
          if (this.#isScanning) return;
          this.#toggleSelect(idx, !this.#selectedMap.get(idx));
        },
      },
      el('div', { class: 'loot-item-check-col' }, checkbox),
      el('span', { class: 'item-glyph' }, def.glyph),
      el(
        'div',
        { class: 'loot-item-details' },
        el(
          'div',
          { class: 'loot-item-title-line' },
          el(
            'strong',
            { class: ['loot-item-name', def.rarity ? `rarity-${def.rarity}` : ''] },
            t(`item.${item.itemId}.name`),
          ),
          el('span', { class: 'loot-item-qty' }, `×${item.qty}`),
        ),
        el(
          'div',
          { class: 'loot-item-meta-row' },
          el(
            'span',
            { class: ['loot-item-rarity', def.rarity ? `rarity-${def.rarity}` : ''] },
            t(`rarity.${def.rarity || 'common'}`),
          ),
          el('span', { class: 'loot-item-weight' }, `${totalItemWeight} kg`),
        ),
      ),
      toggleBtn,
    );

    return row;
  }

  #toggleSelect(idx, val) {
    this.#selectedMap.set(idx, val);
    const rowEl = this.#itemRowEls[idx];
    if (rowEl) {
      rowEl.classList.toggle('is-selected', val);
      const cb = rowEl.querySelector('input[type="checkbox"]');
      if (cb) cb.checked = val;
      const btn = rowEl.querySelector('button');
      if (btn) {
        btn.textContent = val ? '✓' : '−';
        btn.classList.toggle('btn-accent', val);
        btn.classList.toggle('btn-ghost', !val);
      }
    }
    this.#updateCapacityUI();
    this.#updateTakeSelectedBtn();
  }

  #updateCapacityUI() {
    if (!this.#capacityBarEl || !this.#current) return;
    const state = this.#engine.store.state;
    const summary = loadSummary(state);

    let selectedWeight = 0;
    this.#current.items.forEach((item, idx) => {
      if (idx < this.#revealedCount && this.#selectedMap.get(idx)) {
        const itemDef = getItem(item.itemId);
        selectedWeight += itemDef.weight * item.qty;
      }
    });

    const projectedWeight = summary.weight + selectedWeight;
    const isOverload = projectedWeight > summary.capacityKg;

    if (this.#capacityLabelEl) {
      this.#capacityLabelEl.textContent = t('loot.load_status', {
        current: i18n.formatNumber(summary.weight, 1),
        max: i18n.formatNumber(summary.capacityKg, 1),
        selected: i18n.formatNumber(selectedWeight, 2),
      });
    }

    this.#capacityBarEl.classList.toggle('is-overload', isOverload);
    this.#capacityBarEl.style.display = this.#revealedCount > 0 ? 'flex' : 'none';
  }

  #updateTakeSelectedBtn() {
    if (!this.#footerEl) return;
    const btn = this.#footerEl.querySelector('.js-take-selected');
    if (!btn || !this.#current) return;

    let selectedCount = 0;
    this.#current.items.forEach((_, idx) => {
      if (this.#selectedMap.get(idx)) selectedCount += 1;
    });

    btn.textContent = t('loot.action.take_selected', { count: selectedCount });
    btn.disabled = selectedCount === 0;
    btn.classList.toggle('is-disabled', selectedCount === 0);
  }

  #renderUnlockedFooter() {
    if (!this.#footerEl || !this.#current) return;
    const { items, onConfirm } = this.#current;
    const hasItems = items.length > 0;

    let selectedCount = 0;
    items.forEach((_, idx) => {
      if (this.#selectedMap.get(idx)) selectedCount += 1;
    });

    if (hasItems) {
      this.#footerEl.replaceChildren(
        el(
          'button',
          {
            type: 'button',
            class: 'btn btn-ghost loot-action-btn',
            onClick: () => {
              const left = [...items];
              this.close();
              onConfirm?.([], left);
            },
          },
          t('loot.action.leave_all'),
        ),
        el(
          'button',
          {
            type: 'button',
            class: [
              'btn',
              'loot-action-btn',
              'js-take-selected',
              selectedCount === 0 && 'is-disabled',
            ],
            disabled: selectedCount === 0,
            onClick: () => {
              const taken = [];
              const left = [];
              items.forEach((it, idx) => {
                if (this.#selectedMap.get(idx)) taken.push(it);
                else left.push(it);
              });
              this.close();
              onConfirm?.(taken, left);
            },
          },
          t('loot.action.take_selected', { count: selectedCount }),
        ),
        el(
          'button',
          {
            type: 'button',
            class: 'btn btn-accent loot-action-btn',
            onClick: () => {
              const taken = [...items];
              this.close();
              onConfirm?.(taken, []);
            },
          },
          t('loot.action.take_all'),
        ),
      );
    } else {
      this.#footerEl.replaceChildren(
        el(
          'button',
          {
            type: 'button',
            class: 'btn btn-accent loot-action-btn',
            onClick: () => {
              this.close();
              onConfirm?.([], []);
            },
          },
          t('loot.action.close'),
        ),
      );
    }
  }

  #buildInitialCard() {
    const { type, titleKey, descKey, descParams, items } = this.#current;
    const hasItems = items.length > 0;
    const isScavenge = type === 'scavenge' || type === 'scavenge_empty';

    const kickerText = t(titleKey);
    const descText = t(descKey, descParams);

    this.#itemRowEls = [];

    // 1. Radar Scanner Header Box
    let scannerCard = null;
    if (isScavenge) {
      this.#statusTitleEl = el(
        'strong',
        { class: 'scavenge-status-title' },
        this.#isScanning
          ? t('loot.scanner.searching')
          : hasItems
          ? t('loot.scanner.completed')
          : t('loot.scanner.empty_status'),
      );

      this.#counterDigitalEl = el(
        'span',
        { class: ['scavenge-counter-digital', !this.#isScanning && 'is-done'] },
        this.#isScanning ? `%${this.#scanProgress}` : '✓ 100%',
      );

      this.#progressFillEl = el('div', {
        class: ['scavenge-progress-fill', !this.#isScanning && 'is-complete'],
        style: `width: ${this.#scanProgress}%;`,
      });

      this.#telemetryEl = el(
        'span',
        { class: 'scavenge-telemetry' },
        this.#isScanning
          ? t('loot.scanner.telemetry_searching')
          : hasItems
          ? t('loot.scanner.completed_desc', { count: items.length })
          : t('loot.scanner.empty_desc'),
      );

      this.#speedupBtnEl = el(
        'button',
        {
          type: 'button',
          class: 'btn btn-xs btn-accent scavenge-speedup-btn',
          onClick: (e) => {
            e.stopPropagation();
            this.#finishScanImmediately();
          },
        },
        t('loot.scanner.speedup'),
      );

      scannerCard = el(
        'div',
        { class: 'scavenge-counter-card' },
        el(
          'div',
          { class: 'scavenge-counter-header' },
          el(
            'div',
            { class: 'scavenge-header-left' },
            el('span', { class: 'scavenge-radar-pip is-pulsing' }),
            this.#statusTitleEl,
          ),
          el('div', { class: 'scavenge-header-right' }, this.#counterDigitalEl),
        ),
        el('div', { class: 'scavenge-progress-track' }, this.#progressFillEl),
        el('div', { class: 'scavenge-subline' }, this.#telemetryEl, this.#speedupBtnEl),
      );
    }

    // 2. Items List Container
    this.#itemsListEl = el('div', { class: 'loot-items-list' });

    if (isScavenge && this.#isScanning) {
      this.#placeholderEl = el(
        'div',
        { class: 'scavenge-scanning-placeholder' },
        el('span', {}, t('loot.scanner.telemetry_searching')),
      );
      this.#itemsListEl.appendChild(this.#placeholderEl);
    } else if (hasItems) {
      items.forEach((it, idx) => {
        const row = this.#createItemRow(it, idx, false);
        this.#itemRowEls[idx] = row;
        this.#itemsListEl.appendChild(row);
      });
    } else {
      this.#itemsListEl.appendChild(
        el('div', { class: 'loot-empty-note' }, t('loot.no_items')),
      );
    }

    // 3. Capacity Bar
    this.#capacityLabelEl = el('span', { class: 'loot-capacity-label' }, '');
    this.#capacityBarEl = el(
      'div',
      { class: 'loot-capacity-bar', style: 'display: none;' },
      this.#capacityLabelEl,
      el('span', { class: 'loot-overload-alert' }, t('loot.overload_warning')),
    );
    this.#updateCapacityUI();

    // 4. Footer
    this.#footerEl = el('div', { class: 'action-modal-footer' });
    if (this.#isScanning) {
      this.#footerEl.replaceChildren(
        el(
          'button',
          {
            type: 'button',
            class: 'btn btn-accent loot-action-btn',
            onClick: () => this.#finishScanImmediately(),
          },
          t('loot.scanner.speedup'),
        ),
      );
    } else {
      this.#renderUnlockedFooter();
    }

    // 5. Assemble modal card ONCE into DOM
    this.#cardEl = el(
      'div',
      { class: ['action-modal-card', isScavenge && 'scavenge-modal-card'] },
      el(
        'div',
        { class: 'action-modal-header' },
        el('h3', { class: 'action-modal-title' }, kickerText),
      ),
      scannerCard,
      !isScavenge && el('p', { class: 'action-modal-desc' }, descText),
      isScavenge && !this.#isScanning && el('p', { class: 'action-modal-desc' }, descText),
      this.#itemsListEl,
      this.#capacityBarEl,
      this.#footerEl,
    );

    this.#root.replaceChildren(this.#cardEl);
  }

  render() {
    if (!this.#current || this.#root.hidden) return;
    this.#buildInitialCard();
  }
}


  // --- src/ui/barterModalView.js ---





class BarterModalView {
  #root;
  #engine;

  constructor(root, engine) {
    this.#root = root;
    this.#engine = engine;

    engine.bus.on('barter:modal', ({ active }) => {
      if (active) {
        this.open();
      } else {
        this.close();
      }
    });
  }

  get isOpen() {
    return !this.#root.hidden;
  }

  open() {
    this.#root.hidden = false;
    this.render();
  }

  close() {
    this.#root.hidden = true;
    this.#root.replaceChildren();
  }

  render() {
    if (this.#root.hidden) return;

    const state = this.#engine.store.state;
    const session = state.economy?.activeSession;
    if (!session) {
      this.close();
      return;
    }

    const profile = MERCHANT_PROFILES[session.merchantType] || MERCHANT_PROFILES[MERCHANT_TYPES.NOMAD_CARAVAN];
    const merchantTitle = t(`barter.merchant.${session.merchantType}.name`);
    const merchantDesc = t(`barter.merchant.${session.merchantType}.desc`);

    // Prepare arrays for evaluation
    const playerOfferArr = Object.entries(session.playerOffer).map(([itemId, qty]) => ({ itemId, qty }));
    const merchantDemandArr = Object.entries(session.merchantDemands).map(([itemId, qty]) => ({ itemId, qty }));

    const evaluation = BarterEngine.evaluateTrade({
      playerOffer: playerOfferArr,
      merchantDemands: merchantDemandArr,
      merchantType: session.merchantType,
      state,
      haggleDiscount: session.haggleDiscount,
    });

    // 1. Header
    const headerEl = el(
      'div',
      { class: 'action-modal-header' },
      el('div', { class: 'encounter-kicker' }, `${t('barter.kicker')} // ${t(`faction.${session.faction}.name`)}`),
      el('h3', { class: 'action-modal-title' }, merchantTitle),
    );

    // 2. Evaluation Status Bar
    const statusClass = evaluation.isBalanced ? 'is-good' : 'is-danger';
    const statusText = evaluation.isBalanced
      ? `✓ ${t('barter.status_balanced')}`
      : `⚠ ${t('barter.status_insufficient', { diff: Math.abs(evaluation.difference) })}`;

    const evaluationEl = el(
      'div',
      { class: 'barter-eval-bar' },
      el(
        'div',
        { class: 'barter-value-group' },
        el('span', { class: 'muted-note' }, t('barter.player_offered_val')),
        el('strong', { class: 'barter-val-num' }, `${evaluation.playerTotal} pts`),
      ),
      el(
        'div',
        { class: 'barter-value-group' },
        el('span', { class: 'muted-note' }, t('barter.merchant_demanded_val')),
        el('strong', { class: 'barter-val-num' }, `${evaluation.merchantRequiredTotal} pts`),
      ),
      el(
        'div',
        { class: ['barter-status-tag', statusClass] },
        statusText,
      ),
    );

    // 3. Two-Column Exchange Area
    // Left: Player Inventory Stacks
    const playerStacks = state.inventory.stacks || [];
    const playerItemsList = el(
      'div',
      { class: 'barter-column-list' },
      playerStacks.length === 0
        ? el('p', { class: 'muted-note' }, t('barter.player_empty'))
        : playerStacks.map(({ itemId, qty: totalQty }) => {
            const def = getItem(itemId);
            const val = getItemBarterValue(itemId);
            const currentlyOffered = session.playerOffer[itemId] || 0;

            return el(
              'div',
              { class: ['barter-item-row', currentlyOffered > 0 && 'is-active'] },
              el(
                'div',
                { class: 'barter-item-meta' },
                el('span', { class: 'barter-item-name' }, t(`item.${itemId}.name`)),
                el('span', { class: 'muted-note' }, `${val} pts · pack: ${totalQty}`),
              ),
              el(
                'div',
                { class: 'barter-stepper' },
                el(
                  'button',
                  {
                    type: 'button',
                    class: ['btn btn-xs', currentlyOffered === 0 && 'is-disabled'],
                    disabled: currentlyOffered === 0,
                    onClick: () => this.#engine.dispatch('economy/togglePlayerOffer', { itemId, delta: -1 }),
                  },
                  '-',
                ),
                el('span', { class: 'barter-qty-indicator' }, String(currentlyOffered)),
                el(
                  'button',
                  {
                    type: 'button',
                    class: ['btn btn-xs', currentlyOffered >= totalQty && 'is-disabled'],
                    disabled: currentlyOffered >= totalQty,
                    onClick: () => this.#engine.dispatch('economy/togglePlayerOffer', { itemId, delta: 1 }),
                  },
                  '+',
                ),
              ),
            );
          }),
    );

    // Right: Merchant Stock
    const merchantStock = profile.inventoryStock || [];
    const merchantItemsList = el(
      'div',
      { class: 'barter-column-list' },
      merchantStock.map(({ itemId, qty: maxStock }) => {
        const val = getItemBarterValue(itemId);
        const wanted = session.merchantDemands[itemId] || 0;

        return el(
          'div',
          { class: ['barter-item-row', wanted > 0 && 'is-active'] },
          el(
            'div',
            { class: 'barter-item-meta' },
            el('span', { class: 'barter-item-name' }, t(`item.${itemId}.name`)),
            el('span', { class: 'muted-note' }, `${val} pts · stock: ${maxStock}`),
          ),
          el(
            'div',
            { class: 'barter-stepper' },
            el(
              'button',
              {
                type: 'button',
                class: ['btn btn-xs', wanted === 0 && 'is-disabled'],
                disabled: wanted === 0,
                onClick: () => this.#engine.dispatch('economy/toggleMerchantDemand', { itemId, delta: -1 }),
              },
              '-',
            ),
            el('span', { class: 'barter-qty-indicator' }, String(wanted)),
            el(
              'button',
              {
                type: 'button',
                class: ['btn btn-xs', wanted >= maxStock && 'is-disabled'],
                disabled: wanted >= maxStock,
                onClick: () => this.#engine.dispatch('economy/toggleMerchantDemand', { itemId, delta: 1 }),
              },
              '+',
            ),
          ),
        );
      }),
    );

    const columnsGrid = el(
      'div',
      { class: 'barter-columns-grid' },
      el(
        'div',
        { class: 'barter-col' },
        el('div', { class: 'tactical-subhead' }, `🎒 ${t('barter.col_player')}`),
        playerItemsList,
      ),
      el(
        'div',
        { class: 'barter-col' },
        el('div', { class: 'tactical-subhead' }, `📦 ${t('barter.col_merchant')}`),
        merchantItemsList,
      ),
    );

    // 4. Modal Footer Controls
    const canTrade = evaluation.isBalanced && merchantDemandArr.length > 0;
    const footerEl = el(
      'div',
      { class: 'action-modal-footer barter-footer' },
      el(
        'button',
        {
          type: 'button',
          class: ['btn btn-xs', session.haggleAttempted && 'is-disabled'],
          disabled: session.haggleAttempted,
          onClick: () => this.#engine.dispatch('economy/haggle'),
        },
        session.haggleAttempted
          ? `✓ ${t('barter.haggle_done')} (${evaluation.discountPercent}% off)`
          : `💬 ${t('barter.action_haggle')}`,
      ),
      el(
        'button',
        {
          type: 'button',
          class: 'btn btn-xs btn-ghost',
          onClick: () => this.#engine.dispatch('economy/closeBarter'),
        },
        t('barter.action_cancel'),
      ),
      el(
        'button',
        {
          type: 'button',
          class: ['btn btn-xs btn-accent', !canTrade && 'is-disabled'],
          disabled: !canTrade,
          onClick: () => this.#engine.dispatch('economy/executeTrade'),
        },
        `🤝 ${t('barter.action_confirm')}`,
      ),
    );

    const card = el(
      'div',
      { class: 'action-modal-card barter-modal-card' },
      headerEl,
      el('p', { class: 'action-modal-desc' }, merchantDesc),
      evaluationEl,
      columnsGrid,
      footerEl,
    );

    this.#root.replaceChildren(card);
  }
}



  // --- src/ui/vehicleModalView.js ---
/**
 * Last Breath // Vehicle & Overland Travel Modal View
 * Dedicated terminal dossier for vehicle restoration, component installation,
 * modular tuning & attachments (Bullbar, Cargo Rack, Mud Tires, Floodlights, Camper Bed),
 * fuel telemetry, field siphoning, mobile camping, and bidirectional pack/trunk cargo transfer.
 */







class VehicleModalView {
  #rootEl;
  #engine;
  #activeVehicleId = null;

  constructor(rootEl, engine) {
    this.#rootEl = rootEl;
    this.#engine = engine;

    // Listen to store updates
    this.#engine.bus.on('state:changed', () => {
      if (!this.#rootEl.hidden && this.#activeVehicleId) {
        this.render(this.#engine.store.state);
      }
    });

    // Action listener for opening/closing
    this.#engine.bus.on('vehicles:modal', ({ vehicleId }) => {
      if (vehicleId) {
        this.open(vehicleId);
      } else {
        this.close();
      }
    });
  }

  get isOpen() {
    return !this.#rootEl.hidden && Boolean(this.#activeVehicleId);
  }

  open(vehicleId) {
    this.#activeVehicleId = vehicleId;
    this.#rootEl.hidden = false;
    this.render(this.#engine.store.state);
  }

  close() {
    this.#activeVehicleId = null;
    this.#rootEl.hidden = true;
    this.#rootEl.replaceChildren();
    try {
      this.#engine.store.commit('vehicles/closeModal');
    } catch {}
  }

  render(state) {
    if (!this.#activeVehicleId) {
      this.#rootEl.hidden = true;
      return;
    }

    const vehicle = VehicleEngine.getVehicle(state, this.#activeVehicleId);
    const def = VEHICLE_CATALOG[this.#activeVehicleId];
    if (!vehicle || !def) {
      this.close();
      return;
    }

    const isMounted = state.vehicles?.mountedVehicleId === this.#activeVehicleId;
    const maxTrunk = VehicleEngine.getEffectiveTrunkCapacity(vehicle, def);
    const maxFuel = VehicleEngine.getEffectiveMaxFuel(vehicle, def);
    const armorPct = Math.round(VehicleEngine.getEffectiveArmorReduction(vehicle, def) * 100);
    const trunkWeight = VehicleEngine.getCargoWeight(vehicle);
    const trunkPct = Math.min(100, Math.round((trunkWeight / maxTrunk) * 100));
    const fuelPct = Math.min(100, Math.round((vehicle.fuelLiters / maxFuel) * 100));
    const canCamp = VehicleEngine.canCampInVehicle(vehicle, def);

    const card = el(
      'div',
      { class: 'modal-card vehicle-modal-card' },

      // Header Cluster
      el(
        'div',
        { class: 'vehicle-header' },
        el(
          'div',
          { class: 'vehicle-title-cluster' },
          el('span', { class: 'vehicle-glyph' }, def.glyph),
          el(
            'div',
            {},
            el('h2', { class: 'vehicle-title' }, t(def.nameKey)),
            el(
              'div',
              { class: 'vehicle-submeta' },
              el('span', {}, `${t('vehicle.label.sector')}: ${vehicle.nodeId ? t(`location.${vehicle.nodeId}`) : t('vehicle.status.unknown_location')}`),
              el('span', {}, ' · '),
              el(
                'span',
                { class: vehicle.restored ? 'tone-good' : 'tone-warn' },
                vehicle.restored ? t('vehicle.status.operational') : t('vehicle.status.abandoned'),
              ),
              isMounted && el('span', { class: 'tactical-badge is-good' }, `🟢 ${t('vehicle.status.driving')}`),
            ),
          ),
        ),
        el(
          'button',
          {
            type: 'button',
            class: 'btn-modal-close',
            'aria-label': 'Close',
            onClick: () => this.close(),
          },
          '✕',
        ),
      ),

      // Ignition / Mount Control Strip
      (() => {
        const isMuscle = Boolean(def.musclePowered || def.fuelType === 'muscle');
        const canMount = Boolean(vehicle.restored && (isMuscle || vehicle.fuelLiters > 0));
        return el(
          'div',
          { class: 'vehicle-control-strip' },
          isMounted
            ? el(
                'button',
                {
                  type: 'button',
                  class: 'btn btn-warn btn-sm',
                  onClick: () => this.#engine.dispatch('vehicles/dismount'),
                },
                `🛑 ${t('vehicle.action.dismount')}`,
              )
            : el(
                'button',
                {
                  type: 'button',
                  class: ['btn', canMount ? 'btn-accent' : 'btn-disabled', 'btn-sm'],
                  disabled: !canMount,
                  onClick: () => this.#engine.dispatch('vehicles/mount', { vehicleId: this.#activeVehicleId }),
                },
                `🔑 ${t('vehicle.action.mount')}`,
              ),
          el(
            'div',
            { class: 'vehicle-specs-pills' },
            el('span', { class: 'tactical-badge' }, `⚡ ${def.speedMultiplier <= 0.25 ? '4.5x' : '3.0x'} ${t('vehicle.spec.speed')}`),
            el('span', { class: 'tactical-badge' }, `🔊 +${Math.round((def.noiseRiskMultiplier - 1) * 100)}% ${t('vehicle.spec.noise')}`),
            def.cabinShelter && el('span', { class: 'tactical-badge is-good' }, `🛡️ ${t('vehicle.spec.shelter')}`),
            armorPct > 0 && el('span', { class: 'tactical-badge is-good' }, `🔰 ${armorPct}% ${t('vehicle.spec.armor')}`),
            def.amphibious && el('span', { class: 'tactical-badge is-accent' }, `🌊 ${t('vehicle.spec.amphibious')}`),
            def.fuelType === 'electric' && el('span', { class: 'tactical-badge is-accent' }, `⚡ ${t('vehicle.spec.solar_electric')}`),
            isMuscle && el('span', { class: 'tactical-badge is-accent' }, `🚋 ${t('vehicle.spec.muscle_powered')}`),
            def.fieldClinic && el('span', { class: 'tactical-badge is-good' }, `🚑 ${t('vehicle.spec.field_clinic')}`),
            def.arcticTracked && el('span', { class: 'tactical-badge is-good' }, `🚜 ${t('vehicle.spec.arctic_tracked')}`),
          ),
        );
      })(),

      // Telemetry Gauges (Fuel & Engine Health)
      (() => {
        const isMuscle = Boolean(def.musclePowered || def.fuelType === 'muscle');
        return el(
          'div',
          { class: 'vehicle-telemetry-grid' },
          el(
            'div',
            { class: 'vital-row' },
            el(
              'div',
              { class: 'vital-head' },
              el('span', { class: 'vital-label' }, isMuscle ? `🚋 ${t('vehicle.fuel.muscle_label')}` : `⛽ ${t('vehicle.gauge.fuel')} (${def.fuelType.toUpperCase()})`),
              el('span', { class: 'vital-value' }, isMuscle ? '∞ (0 L)' : `${vehicle.fuelLiters.toFixed(1)} / ${maxFuel} ${def.fuelType === 'electric' ? 'kWh' : 'L'}`),
            ),
            el(
              'div',
              { class: 'meter-track' },
              el('div', { class: ['meter-fill', isMuscle ? 'tone-fill-accent' : (fuelPct < 20 ? 'tone-fill-warn' : 'tone-fill-good')], style: `width: ${fuelPct}%` }),
            ),
          ),
          el(
            'div',
            { class: 'vital-row' },
            el(
              'div',
              { class: 'vital-head' },
              el('span', { class: 'vital-label' }, `🛠️ ${t('vehicle.gauge.condition')}`),
              el('span', { class: 'vital-value' }, `${vehicle.condition}%`),
            ),
            el(
              'div',
              { class: 'meter-track' },
              el('div', { class: ['meter-fill', vehicle.condition < 30 ? 'tone-fill-bad' : 'tone-fill-accent'], style: `width: ${vehicle.condition}%` }),
            ),
          ),
        );
      })(),

      // Restoration & Maintenance Section
      this.#renderRestorationBlock(state, vehicle, def, canCamp),

      // Modular Upgrades & Attachments Section
      this.#renderUpgradesBlock(state, vehicle, def),

      // Dual Column Trunk & Pack Cargo Transfer
      this.#renderCargoBay(state, vehicle, def, trunkWeight, trunkPct, maxTrunk),
    );

    this.#rootEl.replaceChildren(card);
  }

  #renderRestorationBlock(state, vehicle, def, canCamp) {
    const isRestored = vehicle.restored;

    // Component Checklist (if not fully restored)
    const partsRows = !isRestored && def.partsRequired.map((req) => {
      const installed = vehicle.installedParts?.[req.itemId] || 0;
      const needed = req.qty;
      const isComplete = installed >= needed;
      const availableItemId = VehicleEngine.findAvailablePartInInventory(state.inventory, req);

      return el(
        'div',
        { class: ['vehicle-part-row', isComplete ? 'is-complete' : 'is-missing'] },
        el(
          'div',
          { class: 'vehicle-part-info' },
          el('span', { class: 'part-icon' }, isComplete ? '✓' : '✗'),
          el('span', { class: 'part-name' }, t(`item.${req.itemId}.name`)),
          el('span', { class: 'part-qty' }, `[${installed} / ${needed}]`),
        ),
        !isComplete && availableItemId && el(
          'button',
          {
            type: 'button',
            class: 'btn btn-accent btn-xs',
            onClick: () => this.#engine.dispatch('vehicles/installPart', {
              vehicleId: vehicle.id,
              reqItemId: req.itemId,
            }),
          },
          `+ ${t('vehicle.action.install')}`,
        ),
        !isComplete && !availableItemId && el(
          'span',
          { class: 'part-missing-tag' },
          t('vehicle.status.missing'),
        ),
      );
    });

    // Quick Refuel / Siphon / Camp Buttons
    const hasGasCan = countItem(state.inventory, 'gasoline_fuel_canister_5l') > 0;
    const hasDiesel5 = countItem(state.inventory, 'diesel_fuel_canister_5l') > 0;
    const hasDiesel10 = countItem(state.inventory, 'diesel_fuel_canister_10l') > 0;
    const hasCarBat1 = countItem(state.inventory, 'car_battery_lead_acid') > 0;
    const hasCarBat2 = countItem(state.inventory, 'car_battery_12v_lead_acid') > 0;
    const hasSiphonHose = countItem(state.inventory, 'fuel_siphon_hose') > 0;
    const hasScrap = countItem(state.inventory, 'scrap_metal') > 0;
    const hasOil = countItem(state.inventory, 'motor_oil_10w40_bottle') > 0 ||
      countItem(state.inventory, 'motor_oil_synthetic_10w40') > 0;

    const maintenanceOps = el(
      'div',
      { class: 'vehicle-maintenance-actions' },
      def.fuelType === 'gasoline' && hasGasCan && el(
        'button',
        {
          type: 'button',
          class: 'btn btn-xs',
          onClick: () => this.#engine.dispatch('vehicles/refuel', {
            vehicleId: vehicle.id,
            canisterItemId: 'gasoline_fuel_canister_5l',
          }),
        },
        `⛽ +5L ${t('item.gasoline_fuel_canister_5l.name')}`,
      ),
      def.fuelType === 'diesel' && hasDiesel5 && el(
        'button',
        {
          type: 'button',
          class: 'btn btn-xs',
          onClick: () => this.#engine.dispatch('vehicles/refuel', {
            vehicleId: vehicle.id,
            canisterItemId: 'diesel_fuel_canister_5l',
          }),
        },
        `⛽ +5L ${t('item.diesel_fuel_canister_5l.name')}`,
      ),
      def.fuelType === 'diesel' && hasDiesel10 && el(
        'button',
        {
          type: 'button',
          class: 'btn btn-xs',
          onClick: () => this.#engine.dispatch('vehicles/refuel', {
            vehicleId: vehicle.id,
            canisterItemId: 'diesel_fuel_canister_10l',
          }),
        },
        `⛽ +10L ${t('item.diesel_fuel_canister_10l.name')}`,
      ),
      def.fuelType === 'electric' && hasCarBat1 && el(
        'button',
        {
          type: 'button',
          class: 'btn btn-xs',
          onClick: () => this.#engine.dispatch('vehicles/refuel', {
            vehicleId: vehicle.id,
            canisterItemId: 'car_battery_lead_acid',
          }),
        },
        `⚡ +12 kWh (${t('item.car_battery_lead_acid.name')})`,
      ),
      def.fuelType === 'electric' && hasCarBat2 && el(
        'button',
        {
          type: 'button',
          class: 'btn btn-xs',
          onClick: () => this.#engine.dispatch('vehicles/refuel', {
            vehicleId: vehicle.id,
            canisterItemId: 'car_battery_12v_lead_acid',
          }),
        },
        `⚡ +18 kWh (${t('item.car_battery_12v_lead_acid.name')})`,
      ),
      hasSiphonHose && def.fuelType !== 'electric' && el(
        'button',
        {
          type: 'button',
          class: 'btn btn-ghost btn-xs',
          onClick: () => this.#engine.dispatch('vehicles/siphon', { vehicleId: vehicle.id }),
        },
        `🧪 ${t('vehicle.action.siphon')}`,
      ),
      hasScrap && vehicle.condition < 100 && el(
        'button',
        {
          type: 'button',
          class: 'btn btn-ghost btn-xs',
          onClick: () => this.#engine.dispatch('vehicles/repair', {
            vehicleId: vehicle.id,
            repairItemId: 'scrap_metal',
          }),
        },
        `🔨 +10% ${t('vehicle.action.repair_scrap')}`,
      ),
      hasOil && vehicle.condition < 100 && el(
        'button',
        {
          type: 'button',
          class: 'btn btn-ghost btn-xs',
          onClick: () => this.#engine.dispatch('vehicles/repair', {
            vehicleId: vehicle.id,
            repairItemId: countItem(state.inventory, 'motor_oil_10w40_bottle') > 0
              ? 'motor_oil_10w40_bottle'
              : 'motor_oil_synthetic_10w40',
          }),
        },
        `🛢️ +25% ${t('vehicle.action.repair_oil')}`,
      ),
      canCamp && el(
        'button',
        {
          type: 'button',
          class: 'btn btn-accent btn-xs',
          onClick: () => this.#engine.dispatch('vehicles/camp', { vehicleId: vehicle.id, hours: 4 }),
        },
        `⛺ ${t('vehicle.action.camp_4h')}`,
      ),
      canCamp && el(
        'button',
        {
          type: 'button',
          class: 'btn btn-accent btn-xs',
          onClick: () => this.#engine.dispatch('vehicles/camp', { vehicleId: vehicle.id, hours: 8 }),
        },
        `⛺ ${t('vehicle.action.camp_8h')}`,
      ),
    );

    return el(
      'section',
      { class: 'vehicle-section' },
      el('h3', { class: 'block-title' }, isRestored ? t('vehicle.section.maintenance') : t('vehicle.section.restoration')),
      !isRestored && el('div', { class: 'vehicle-parts-list' }, partsRows),
      maintenanceOps,
    );
  }

  #renderUpgradesBlock(state, vehicle, def) {
    if (!vehicle.restored) return null;

    const upgradesList = Object.values(VEHICLE_UPGRADES).map((upDef) => {
      const isInstalled = VehicleEngine.hasUpgrade(vehicle, upDef.id);
      let canCraft = true;

      const reqPills = upDef.requiredItems.map((req) => {
        const hasPart = VehicleEngine.findAvailablePartInInventory(state.inventory, req);
        const count = hasPart ? countItem(state.inventory, hasPart) : 0;
        const satisfied = count >= req.qty;
        if (!satisfied) canCraft = false;

        return el(
          'span',
          { class: `ing-pill ${satisfied ? 'tone-good' : 'tone-bad'}` },
          `${t(`item.${req.itemId}.name`)} (${count}/${req.qty})`,
        );
      });

      return el(
        'div',
        { class: `vehicle-upgrade-card ${isInstalled ? 'is-installed' : ''}` },
        el(
          'div',
          { class: 'upgrade-card-head' },
          el('span', { class: 'upgrade-icon' }, upDef.icon),
          el(
            'div',
            { class: 'upgrade-title-cluster' },
            el('strong', { class: 'upgrade-name' }, t(upDef.nameKey)),
            el('p', { class: 'upgrade-desc' }, t(upDef.descKey)),
          ),
          isInstalled
            ? el('span', { class: 'tactical-badge is-good' }, `✔ ${t('vehicle.status.installed')}`)
            : (canCraft
                ? el(
                    'button',
                    {
                      type: 'button',
                      class: 'btn btn-accent btn-xs',
                      onClick: () => this.#engine.dispatch('vehicles/installUpgrade', {
                        vehicleId: vehicle.id,
                        upgradeId: upDef.id,
                      }),
                    },
                    `+ ${t('vehicle.action.install_upgrade')}`,
                  )
                : el('span', { class: 'part-missing-tag' }, t('vehicle.status.missing_materials'))),
        ),
        !isInstalled && el('div', { class: 'upgrade-reqs-row' }, reqPills),
      );
    });

    return el(
      'section',
      { class: 'vehicle-section vehicle-upgrades-section' },
      el('h3', { class: 'block-title' }, `🛠️ ${t('vehicle.section.upgrades')}`),
      el('div', { class: 'vehicle-upgrades-grid' }, upgradesList),
    );
  }

  #renderCargoBay(state, vehicle, def, trunkWeight, trunkPct, maxTrunk) {
    const packStacks = state.inventory.stacks || [];
    const trunkStacks = vehicle.cargo || [];

    // Left Column: Survivor Pack
    const packItems = packStacks.map((stack) => {
      const item = getItem(stack.itemId);
      return el(
        'li',
        { class: 'cargo-item-row' },
        el(
          'div',
          { class: 'cargo-item-meta' },
          el('span', { class: 'item-glyph' }, item?.glyph || '•'),
          el('span', { class: 'item-title' }, t(`item.${stack.itemId}.name`)),
          el('span', { class: 'item-qty' }, `x${stack.qty}`),
        ),
        el(
          'div',
          { class: 'cargo-item-buttons' },
          el(
            'button',
            {
              type: 'button',
              class: 'btn btn-ghost btn-xs',
              onClick: () => this.#engine.dispatch('vehicles/toCargo', {
                vehicleId: vehicle.id,
                itemId: stack.itemId,
                qty: 1,
              }),
            },
            '1x →',
          ),
          stack.qty > 1 && el(
            'button',
            {
              type: 'button',
              class: 'btn btn-ghost btn-xs',
              onClick: () => this.#engine.dispatch('vehicles/toCargo', {
                vehicleId: vehicle.id,
                itemId: stack.itemId,
                qty: stack.qty,
              }),
            },
            'All →',
          ),
        ),
      );
    });

    // Right Column: Vehicle Trunk
    const trunkItems = trunkStacks.map((stack) => {
      const item = getItem(stack.itemId);
      return el(
        'li',
        { class: 'cargo-item-row' },
        el(
          'div',
          { class: 'cargo-item-meta' },
          el('span', { class: 'item-glyph' }, item?.glyph || '•'),
          el('span', { class: 'item-title' }, t(`item.${stack.itemId}.name`)),
          el('span', { class: 'item-qty' }, `x${stack.qty}`),
        ),
        el(
          'div',
          { class: 'cargo-item-buttons' },
          el(
            'button',
            {
              type: 'button',
              class: 'btn btn-ghost btn-xs',
              onClick: () => this.#engine.dispatch('vehicles/toPack', {
                vehicleId: vehicle.id,
                itemId: stack.itemId,
                qty: 1,
              }),
            },
            '← 1x',
          ),
          stack.qty > 1 && el(
            'button',
            {
              type: 'button',
              class: 'btn btn-ghost btn-xs',
              onClick: () => this.#engine.dispatch('vehicles/toPack', {
                vehicleId: vehicle.id,
                itemId: stack.itemId,
                qty: stack.qty,
              }),
            },
            '← All',
          ),
        ),
      );
    });

    return el(
      'section',
      { class: 'vehicle-section vehicle-cargo-section' },
      el(
        'div',
        { class: 'cargo-bay-head' },
        el('h3', { class: 'block-title' }, `📦 ${t('vehicle.section.cargo_bay')}`),
        el(
          'div',
          { class: 'trunk-capacity-strip' },
          el('span', {}, `${t('vehicle.label.trunk_load')}: `),
          el('strong', {}, `${trunkWeight} / ${maxTrunk} kg`),
          el(
            'div',
            { class: 'meter-track meter-track-sm' },
            el('div', { class: 'meter-fill tone-fill-good', style: `width: ${trunkPct}%` }),
          ),
        ),
      ),
      el(
        'div',
        { class: 'cargo-bay-grid' },
        el(
          'div',
          { class: 'cargo-bay-col' },
          el('h4', { class: 'cargo-col-title' }, `🎒 ${t('vehicle.label.pack_inventory')}`),
          packItems.length > 0
            ? el('ul', { class: 'cargo-items-list' }, packItems)
            : el('p', { class: 'muted-note' }, t('vehicle.label.pack_empty')),
        ),
        el(
          'div',
          { class: 'cargo-bay-col' },
          el('h4', { class: 'cargo-col-title' }, `🚙 ${t('vehicle.label.trunk_inventory')}`),
          trunkItems.length > 0
            ? el('ul', { class: 'cargo-items-list' }, trunkItems)
            : el('p', { class: 'muted-note' }, t('vehicle.label.trunk_empty')),
        ),
      ),
    );
  }
}


  // --- src/ui/vehicleDiscoveryModalView.js ---
/**
 * Last Breath // Vehicle Discovery Modal View
 * Terminal popup overlay appearing when an abandoned/derelict vehicle is discovered
 * anywhere in the world. Displays telemetry, required restoration parts, and
 * allows claiming directly into the player's inventory/fleet.
 */









class VehicleDiscoveryModalView {
  #rootEl;
  #engine;
  #current = null;

  constructor(rootEl, engine) {
    this.#rootEl = rootEl;
    this.#engine = engine;

    // Listen to vehicle discovery events
    this.#engine.bus.on('vehicles:discovered', (payload) => {
      this.open(payload);
    });
  }

  get isOpen() {
    return !this.#rootEl.hidden && Boolean(this.#current);
  }

  open({ vehicleId, nodeId, source }) {
    this.#current = { vehicleId, nodeId, source };
    this.#rootEl.hidden = false;
    try { audioEngine.playEngineRev(); } catch {}
    this.render();
  }

  close() {
    this.#current = null;
    this.#rootEl.hidden = true;
    this.#rootEl.replaceChildren();
  }

  render() {
    if (!this.#current || this.#rootEl.hidden) return;

    const { vehicleId, nodeId } = this.#current;
    const state = this.#engine.store.state;
    const vehicle = VehicleEngine.getVehicle(state, vehicleId);
    const def = VEHICLE_CATALOG[vehicleId];
    if (!vehicle || !def) {
      this.close();
      return;
    }

    const node = getNode(nodeId);
    const nodeName = node ? t(`location.${node.id}`) : nodeId;
    const countryName = node?.country || '';
    const isMuscle = Boolean(def.musclePowered || def.fuelType === 'muscle');
    const maxFuel = VehicleEngine.getEffectiveMaxFuel(vehicle, def);
    const maxTrunk = VehicleEngine.getEffectiveTrunkCapacity(vehicle, def);
    const speedRatio = def.speedMultiplier ? (1 / def.speedMultiplier).toFixed(1) : '1.0';

    // Rarity / tag
    let roleTag = t('vehicle.discovery.tag_derelict');
    if (def.fieldClinic) roleTag = `🚑 ${t('vehicle.spec.field_clinic')}`;
    else if (def.arcticTracked) roleTag = `🚜 ${t('vehicle.spec.arctic_tracked')}`;
    else if (isMuscle) roleTag = `🚋 ${t('vehicle.spec.muscle_powered')}`;
    else if (def.amphibious) roleTag = `🚤 ${t('vehicle.spec.amphibious')}`;

    // Check parts requirements in inventory
    const partBadges = def.partsRequired.map((req) => {
      const owned = countItem(state.inventory, req.itemId);
      const hasAlternates = Array.isArray(req.alternates)
        ? req.alternates.some((alt) => countItem(state.inventory, alt) >= req.qty)
        : false;
      const satisfied = owned >= req.qty || hasAlternates;
      return el(
        'div',
        { class: ['disc-part-chip', satisfied ? 'is-satisfied' : 'is-missing'].join(' ') },
        el('span', {}, satisfied ? '✓' : '✗'),
        el('span', {}, `${t(`item.${req.itemId}.name`)} (x${req.qty})`),
        el('span', { class: 'disc-part-status' }, satisfied ? t('vehicle.status.installed') : t('vehicle.status.missing')),
      );
    });

    const card = el(
      'div',
      { class: 'action-modal-card vehicle-discovery-card' },
      // Header
      el(
        'div',
        { class: 'action-modal-header vehicle-disc-header' },
        el(
          'div',
          { class: 'vehicle-disc-title-cluster' },
          el('span', { class: 'vehicle-disc-alert-icon' }, '🚨'),
          el(
            'div',
            {},
            el('h3', { class: 'action-modal-title' }, t('vehicle.discovery.title')),
            el('span', { class: 'vehicle-disc-subtitle' }, `📍 ${nodeName} ${countryName ? `(${countryName})` : ''}`),
          ),
        ),
        el('span', { class: 'disc-role-badge' }, roleTag),
      ),
      // Visual Body
      el(
        'div',
        { class: 'vehicle-disc-body' },
        el(
          'div',
          { class: 'vehicle-disc-hero' },
          el('div', { class: 'vehicle-disc-glyph' }, def.glyph || '🚙'),
          el(
            'div',
            { class: 'vehicle-disc-info' },
            el('h2', { class: 'vehicle-disc-name' }, t(def.nameKey)),
            el('p', { class: 'vehicle-disc-desc' }, t(def.descKey)),
          ),
        ),
        // Telemetry Grid
        el(
          'div',
          { class: 'vehicle-disc-telemetry' },
          el(
            'div',
            { class: 'disc-tel-col' },
            el('span', { class: 'disc-tel-label' }, t('vehicle.gauge.condition')),
            el('strong', { class: 'disc-tel-val tone-warn' }, `%${vehicle.condition}`),
          ),
          el(
            'div',
            { class: 'disc-tel-col' },
            el('span', { class: 'disc-tel-label' }, isMuscle ? t('vehicle.fuel.muscle_label') : t('vehicle.gauge.fuel')),
            el('strong', { class: 'disc-tel-val tone-good' }, isMuscle ? '∞ (0 L)' : `${vehicle.fuelLiters}/${maxFuel} L`),
          ),
          el(
            'div',
            { class: 'disc-tel-col' },
            el('span', { class: 'disc-tel-label' }, t('vehicle.trunk_load')),
            el('strong', { class: 'disc-tel-val' }, `${maxTrunk} kg`),
          ),
          el(
            'div',
            { class: 'disc-tel-col' },
            el('span', { class: 'disc-tel-label' }, t('vehicle.spec.speed')),
            el('strong', { class: 'disc-tel-val' }, `${speedRatio}x`),
          ),
        ),
        // Required Restoration Parts
        el(
          'div',
          { class: 'vehicle-disc-parts-section' },
          el('h4', { class: 'disc-section-title' }, t('vehicle.discovery.parts_needed_title')),
          el('div', { class: 'disc-parts-grid' }, ...partBadges),
        ),
      ),
      // Footer Actions
      el(
        'div',
        { class: 'action-modal-footer vehicle-disc-footer' },
        el(
          'button',
          {
            type: 'button',
            class: 'btn btn-accent btn-disc-claim',
            onClick: () => {
              this.#engine.dispatch('vehicles/claim', { vehicleId });
              this.close();
            },
          },
          `🔑 ${t('vehicle.discovery.action_claim_inventory')}`,
        ),
        el(
          'button',
          {
            type: 'button',
            class: 'btn btn-ghost',
            onClick: () => {
              this.#engine.dispatch('vehicles/claim', { vehicleId });
              this.close();
              this.#engine.dispatch('vehicles/openModal', { vehicleId });
            },
          },
          `🛠️ ${t('vehicle.discovery.action_inspect_now')}`,
        ),
        el(
          'button',
          {
            type: 'button',
            class: 'btn btn-ghost',
            onClick: () => this.close(),
          },
          `📍 ${t('vehicle.discovery.action_leave_sector')}`,
        ),
      ),
    );

    this.#rootEl.replaceChildren(card);
  }
}


  // --- src/ui/codexModalView.js ---
/**
 * Last Breath // Codex, Permadeath Memorial & Career Statistics View
 * Interactive terminal dossier governing the fallen survivors graveyard,
 * career telemetry dials, achievement medals, and classified post-collapse lore.
 */





class CodexModalView {
  #rootEl;
  #engine;
  #activeTab = 'memorial'; // 'memorial' | 'achievements' | 'career' | 'lore'

  constructor(rootEl, engine) {
    this.#rootEl = rootEl;
    this.#engine = engine;
    codexManager.setBus(engine.bus);

    // Achievement unlock banner listener
    engine.bus.on('codex:achievement_unlocked', ({ id, catalog }) => {
      this.#showUnlockToast(catalog);
      if (!this.#rootEl.hidden) {
        this.render();
      }
    });

    // Listen for direct open/close modal events
    engine.bus.on('codex:modal', ({ tab } = {}) => {
      if (tab) this.#activeTab = tab;
      this.open();
    });
  }

  open(tab = 'memorial') {
    this.#activeTab = tab;
    this.#rootEl.hidden = false;
    this.render();
  }

  close() {
    this.#rootEl.hidden = true;
    this.#rootEl.replaceChildren();
  }

  #showUnlockToast(catalog) {
    const toast = document.getElementById('toast-banner');
    if (!toast) return;
    toast.textContent = `🏆 ${t('codex.toast_unlocked')}: ${t(catalog.titleKey)}`;
    toast.classList.add('is-visible');
    setTimeout(() => {
      toast.classList.remove('is-visible');
    }, 4500);
  }

  render() {
    if (this.#rootEl.hidden) return;

    const rank = codexManager.getSurvivalRank();
    const achievements = codexManager.achievements;
    const totalAch = Object.keys(ACHIEVEMENTS_CATALOG).length;
    const unlockedAch = Object.keys(achievements).length;

    const card = el(
      'div',
      { class: 'modal-card codex-modal-card' },

      // Header Cluster
      el(
        'div',
        { class: 'codex-header' },
        el(
          'div',
          { class: 'codex-title-cluster' },
          el('span', { class: 'codex-header-glyph' }, '📖'),
          el(
            'div',
            {},
            el('h2', { class: 'codex-title' }, t('codex.title')),
            el(
              'div',
              { class: 'codex-submeta' },
              el('span', {}, `${t('codex.label.rank')}: ${rank.glyph} ${t(rank.rankKey)}`),
              el('span', {}, ' · '),
              el('span', { class: 'tone-amber' }, `${unlockedAch} / ${totalAch} ${t('codex.label.achievements')}`),
            ),
          ),
        ),
        el(
          'button',
          {
            type: 'button',
            class: 'btn btn-ghost btn-xs',
            onClick: () => this.close(),
          },
          '✕',
        ),
      ),

      // Dossier Tab Switcher
      el(
        'div',
        { class: 'codex-tab-bar' },
        [
          { id: 'memorial', labelKey: 'codex.tab.memorial', glyph: '🪦' },
          { id: 'achievements', labelKey: 'codex.tab.achievements', glyph: '🏆' },
          { id: 'career', labelKey: 'codex.tab.career', glyph: '📊' },
          { id: 'lore', labelKey: 'codex.tab.lore', glyph: '📁' },
        ].map((tab) =>
          el(
            'button',
            {
              type: 'button',
              class: ['codex-tab-btn', this.#activeTab === tab.id && 'is-active'],
              onClick: () => {
                this.#activeTab = tab.id;
                this.render();
              },
            },
            `${tab.glyph} ${t(tab.labelKey)}`,
          ),
        ),
      ),

      // Tab Content Body
      el('div', { class: 'codex-body' }, this.#renderActiveTabContent()),
    );

    this.#rootEl.replaceChildren(card);
  }

  #renderActiveTabContent() {
    switch (this.#activeTab) {
      case 'memorial':
        return this.#renderMemorialTab();
      case 'achievements':
        return this.#renderAchievementsTab();
      case 'career':
        return this.#renderCareerTab();
      case 'lore':
        return this.#renderLoreTab();
      default:
        return el('div', {}, 'Unknown Tab');
    }
  }

  // =========================================================================
  // 1. MEMORIAL GRAVEYARD TAB
  // =========================================================================
  #renderMemorialTab() {
    const records = codexManager.memorial;

    if (records.length === 0) {
      return el(
        'div',
        { class: 'memorial-empty-state' },
        el('div', { class: 'empty-glyph' }, '🕯️'),
        el('h3', { class: 'empty-title' }, t('codex.memorial.empty_title')),
        el('p', { class: 'empty-desc' }, t('codex.memorial.empty_desc')),
      );
    }

    const items = records.map((survivor) => {
      const dateStr = new Date(survivor.diedAtTimestamp).toLocaleDateString(
        i18n.locale === 'tr' ? 'tr-TR' : 'en-US',
        { year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' },
      );

      return el(
        'div',
        { class: 'memorial-card' },
        el(
          'div',
          { class: 'memorial-card-head' },
          el(
            'div',
            { class: 'memorial-name-cluster' },
            el('span', { class: 'memorial-rip-icon' }, '✟'),
            el('strong', { class: 'memorial-name' }, survivor.name),
            el('span', { class: 'memorial-archetype-tag' }, t(`archetype.${survivor.archetype}.name`)),
          ),
          el('span', { class: 'memorial-date' }, dateStr),
        ),
        el(
          'div',
          { class: 'memorial-vital-stats' },
          el('span', {}, `📍 ${t(`location.${survivor.deathLocation}`)}`),
          el('span', {}, ' · '),
          el('span', { class: 'tone-warn' }, `💀 ${t(`death.cause.${survivor.causeOfDeath}`)}`),
          el('span', {}, ' · '),
          el('span', {}, `⏳ ${survivor.daysSurvived} ${t('codex.label.days_survived')}`),
          el('span', {}, ' · '),
          el('span', {}, `🗺️ ${survivor.sectorsVisited} ${t('codex.label.sectors')}`),
          el('span', {}, ' · '),
          el('span', {}, `⚔️ ${survivor.enemiesNeutralized} ${t('codex.label.kills')}`),
        ),
        el('blockquote', { class: 'memorial-epitaph' }, `"${survivor.epitaph}"`),
      );
    });

    return el(
      'div',
      { class: 'memorial-list-container' },
      el('div', { class: 'memorial-header-intro' }, el('p', {}, t('codex.memorial.intro_text'))),
      el('div', { class: 'memorial-cards-list' }, items),
    );
  }

  // =========================================================================
  // 2. ACHIEVEMENTS & MEDALS TAB
  // =========================================================================
  #renderAchievementsTab() {
    const userAch = codexManager.achievements;
    const allAchs = Object.values(ACHIEVEMENTS_CATALOG);

    const cards = allAchs.map((ach) => {
      const isUnlocked = Boolean(userAch[ach.id]);
      const unlockDate = isUnlocked
        ? new Date(userAch[ach.id].unlockedAt).toLocaleDateString(i18n.locale === 'tr' ? 'tr-TR' : 'en-US', {
            month: 'short',
            day: 'numeric',
            year: 'numeric',
          })
        : null;

      return el(
        'div',
        { class: ['achievement-badge-card', isUnlocked ? 'is-unlocked' : 'is-locked'] },
        el('div', { class: 'ach-icon' }, isUnlocked ? ach.icon : '🔒'),
        el(
          'div',
          { class: 'ach-meta' },
          el('h4', { class: 'ach-title' }, t(ach.titleKey)),
          el('p', { class: 'ach-desc' }, t(ach.descKey)),
          el(
            'span',
            { class: ['ach-date', isUnlocked ? 'tone-good' : 'tone-dim'] },
            isUnlocked ? `✓ ${unlockDate}` : t('codex.label.locked'),
          ),
        ),
      );
    });

    return el('div', { class: 'achievements-grid' }, cards);
  }

  // =========================================================================
  // 3. CAREER STATISTICS TAB
  // =========================================================================
  #renderCareerTab() {
    const c = codexManager.career;
    const rank = codexManager.getSurvivalRank();

    const statRows = [
      { label: t('codex.stats.total_expeditions'), val: c.totalExpeditions, glyph: '🏕️' },
      { label: t('codex.stats.total_days'), val: `${c.totalDaysSurvived} ${t('codex.label.days')}`, glyph: '⏳' },
      { label: t('codex.stats.total_km'), val: `${c.totalKmTraveled} km`, glyph: '🧭' },
      { label: t('codex.stats.total_sectors'), val: c.totalSectorsVisited, glyph: '🗺️' },
      { label: t('codex.stats.enemies_neutralized'), val: c.totalEnemiesDefeated, glyph: '⚔️' },
      { label: t('codex.stats.enemies_spared'), val: c.totalEnemiesSpared, glyph: '🕊️' },
      { label: t('codex.stats.barter_volume'), val: `${c.totalBarterValue} pts`, glyph: '⚖️' },
      { label: t('codex.stats.vehicles_restored'), val: c.totalVehiclesRestored, glyph: '🚙' },
      { label: t('codex.stats.fuel_siphoned'), val: `${c.totalFuelSiphoned} L`, glyph: '⛽' },
      { label: t('codex.stats.crafts_done'), val: c.totalCraftsDone, glyph: '⚒️' },
    ];

    return el(
      'div',
      { class: 'career-container' },
      // Rank Hero Card
      el(
        'div',
        { class: 'career-rank-hero' },
        el('div', { class: 'rank-glyph' }, rank.glyph),
        el(
          'div',
          { class: 'rank-details' },
          el('span', { class: 'meta-label' }, t('codex.label.career_standing')),
          el('h3', { class: 'rank-title' }, t(rank.rankKey)),
          el('p', { class: 'rank-desc' }, t(`codex.rank.desc_${rank.tier}`)),
        ),
      ),

      // Dials Grid
      el(
        'div',
        { class: 'career-dials-grid' },
        statRows.map((row) =>
          el(
            'div',
            { class: 'career-dial-card' },
            el('span', { class: 'dial-glyph' }, row.glyph),
            el('span', { class: 'dial-label' }, row.label),
            el('strong', { class: 'dial-value' }, row.val),
          ),
        ),
      ),
    );
  }

  // =========================================================================
  // 4. CLASSIFIED LORE CODEX TAB
  // =========================================================================
  #renderLoreTab() {
    const entries = Object.values(LORE_CODEX_CATALOG);

    const categories = [
      { id: 'factions', title: t('codex.lore_cat.factions') },
      { id: 'tactics', title: t('codex.lore_cat.tactics') },
      { id: 'vehicles', title: t('codex.lore_cat.vehicles') },
    ];

    const blocks = categories.map((cat) => {
      const catEntries = entries.filter((e) => e.category === cat.id);
      return el(
        'div',
        { class: 'lore-category-block' },
        el('h4', { class: 'lore-cat-title' }, cat.title),
        el(
          'div',
          { class: 'lore-entries-grid' },
          catEntries.map((e) =>
            el(
              'div',
              { class: 'lore-dossier-card' },
              el(
                'div',
                { class: 'lore-dossier-head' },
                el('span', { class: 'lore-glyph' }, e.glyph),
                el('h5', { class: 'lore-title' }, t(e.titleKey)),
                el('span', { class: 'lore-stamp' }, `[${t('codex.lore.cleared')}]`),
              ),
              el('p', { class: 'lore-text' }, t(e.descKey)),
            ),
          ),
        ),
      );
    });

    return el('div', { class: 'lore-container' }, blocks);
  }
}



  // --- src/ui/radioModalView.js ---
/**
 * Last Breath // Radio & Signal Intercept Modal View
 * Tactical analog/digital field transceiver interface with interactive tuner,
 * real-time S-meter signal strength, oscilloscope visualization, Morse demodulation,
 * emergency dynamo charging, animated auto-scanning, and sector map beacon plotting.
 */







class RadioModalView {
  #rootEl;
  #engine;
  #isOpen = false;
  #scanTimer = null;
  #lastAudioTick = 0;

  // DOM node references for in-place updates (avoids destroying DOM during slider dragging)
  #vfdDisplayEl = null;
  #vfdFreqEl = null;
  #smeterBarEl = null;
  #lockLedEl = null;
  #lockLabelEl = null;
  #signalPctEl = null;
  #sliderEl = null;
  #waveformEl = null;
  #oscStatusEl = null;
  #transcriptContainerEl = null;
  #batteryValEl = null;
  #bookmarkBtnEl = null;
  #scanBtnEl = null;
  #powerBtnEl = null;
  #presetsContainerEl = null;
  #wasLocked = false;

  constructor(rootEl, engine) {
    this.#rootEl = rootEl;
    this.#engine = engine;

    // React to store updates
    const onUpdate = () => {
      if (this.#isOpen) {
        this.#syncView(this.#engine.store.state);
      }
      this.updateHeaderBadge(this.#engine.store.state);
    };

    this.#engine.bus.on('state:changed', onUpdate);
    this.#engine.bus.on('state:replaced', onUpdate);

    this.#rootEl.addEventListener('click', (e) => {
      if (e.target === this.#rootEl) {
        this.close();
      }
    });

    window.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && this.#isOpen) {
        this.close();
      }
    });
  }

  get isOpen() {
    return this.#isOpen;
  }

  render(state) {
    const s = state || this.#engine.store.state;
    if (this.#isOpen) {
      this.#syncView(s);
    }
    this.updateHeaderBadge(s);
  }

  open() {
    this.#isOpen = true;
    this.#rootEl.hidden = false;
    try {
      audioEngine.playTerminalBoot();
    } catch (_) {}
    this.#buildModal(this.#engine.store.state);
  }

  close() {
    this.stopAutoScan();
    this.#isOpen = false;
    this.#rootEl.hidden = true;
    this.#rootEl.replaceChildren();
  }

  updateHeaderBadge(state) {
    const badge = document.getElementById('radio-signal-badge');
    if (!badge) return;

    const hasIncoming = RadioEngine.hasUndiscoveredSignalInRange(state);
    badge.hidden = !hasIncoming;
  }

  #tune(targetFreq, playAudio = true) {
    const clamped = RadioEngine.formatFrequency(targetFreq);
    this.#engine.dispatch('radio/tune', { freq: clamped });

    if (playAudio) {
      const now = performance.now();
      if (now - this.#lastAudioTick > 90) {
        try {
          audioEngine.playRadioDialTick();
        } catch (_) {}
        this.#lastAudioTick = now;
      }
    }
  }

  startAutoScan() {
    if (this.#scanTimer) {
      this.stopAutoScan();
      return;
    }

    const state = this.#engine.store.state;
    const radioState = state.radio || RadioEngine.getInitialState();
    if (!radioState.isPowered || radioState.batteryMinutes <= 0) return;

    try {
      audioEngine.playRadioMorseChirp();
    } catch (_) {}
    if (this.#scanBtnEl) {
      this.#scanBtnEl.textContent = '⏹ STOP SCAN';
      this.#scanBtnEl.classList.add('is-scanning');
    }
    if (this.#oscStatusEl) {
      this.#oscStatusEl.textContent = 'AUTO-SCANNING WAVELENGTHS... [PRESS SCAN TO STOP]';
    }

    this.#scanTimer = setInterval(() => {
      const current = this.#engine.store.state.radio?.activeFrequency || MIN_FREQUENCY;
      let next = Math.round((current + 0.2) * 10) / 10;
      if (next > MAX_FREQUENCY) next = MIN_FREQUENCY;

      this.#tune(next, false);
      try {
        audioEngine.playRadioDialTick(0.12);
      } catch (_) {}

      const rec = RadioEngine.getActiveReception(this.#engine.store.state);
      if (rec.isLocked) {
        this.stopAutoScan();
        try {
          audioEngine.playRadioMorseChirp();
        } catch (_) {}
      }
    }, 60);
  }

  stopAutoScan() {
    if (this.#scanTimer) {
      clearInterval(this.#scanTimer);
      this.#scanTimer = null;
    }
    if (this.#scanBtnEl) {
      this.#scanBtnEl.textContent = '⚡ AUTO-SCAN';
      this.#scanBtnEl.classList.remove('is-scanning');
    }
  }

  #buildModal(state) {
    const radioState = state.radio || RadioEngine.getInitialState();
    const isPowered = Boolean(radioState.isPowered && radioState.batteryMinutes > 0);

    // Create persistent reactive elements
    this.#vfdFreqEl = el('span', { class: 'vfd-frequency' }, radioState.activeFrequency.toFixed(1));
    this.#batteryValEl = el(
      'strong',
      { class: radioState.batteryMinutes > 30 ? 'tone-good' : 'tone-bad' },
      `${radioState.batteryMinutes}m`
    );
    this.#lockLedEl = el('span', { class: 'lock-led' }, '●');
    this.#lockLabelEl = el('span', {}, t('radio.ui.scanning_carrier'));
    this.#signalPctEl = el('strong', {}, '0%');

    this.#smeterBarEl = el(
      'div',
      { class: 'radio-smeter-bar' },
      ...Array.from({ length: 12 }).map(() => el('span', { class: 'smeter-segment' }))
    );

    this.#waveformEl = el('div', { class: 'oscilloscope-waveform is-noise-wave' });
    this.#oscStatusEl = el(
      'div',
      { class: 'oscilloscope-status-line' },
      'AUDIO DEMODULATOR: CARRIER NOISE / SQUELCH ACTIVE'
    );

    this.#transcriptContainerEl = el('div', { class: 'radio-transcript-panel' });

    // Slider
    this.#sliderEl = el('input', {
      type: 'range',
      class: 'radio-freq-slider',
      min: MIN_FREQUENCY,
      max: MAX_FREQUENCY,
      step: FREQUENCY_STEP,
      value: radioState.activeFrequency,
      oninput: (e) => {
        const val = parseFloat(e.target.value);
        this.#tune(val, true);
      },
    });

    this.#bookmarkBtnEl = el(
      'button',
      {
        type: 'button',
        class: 'btn btn-ghost btn-sm btn-fkey',
        onclick: () => this.#engine.dispatch('radio/toggleBookmark', { freq: this.#engine.store.state.radio.activeFrequency }),
      },
      '☆ SAVE'
    );

    const card = el(
      'div',
      { class: 'modal-card radio-modal-card' },

      // Header Bar
      el(
        'div',
        { class: 'radio-header-bar' },
        el(
          'div',
          { class: 'radio-title-cluster' },
          el('span', { class: 'radio-glyph' }, '📻'),
          el(
            'div',
            {},
            el('h2', { class: 'radio-title' }, t('radio.ui.title')),
            el(
              'div',
              { class: 'radio-model-tag' },
              'AN/PRC-117F FIELD TRANSCEIVER // VHF/FM MULTI-BAND'
            )
          )
        ),
        el(
          'div',
          { class: 'radio-header-controls' },
          (this.#powerBtnEl = el(
            'button',
            {
              type: 'button',
              class: `btn btn-xs ${isPowered ? 'btn-accent' : 'btn-ghost'}`,
              onclick: () => this.#engine.dispatch('radio/togglePower'),
            },
            isPowered ? `🟢 ${t('radio.ui.pwr_on')}` : `🔴 ${t('radio.ui.pwr_off')}`
          )),
          el(
            'button',
            {
              type: 'button',
              class: 'btn-modal-close',
              'aria-label': 'Close',
              onclick: () => this.close(),
            },
            '✕'
          )
        )
      ),

      // Transceiver Body
      el(
        'div',
        { class: 'radio-terminal-body' },

        // Telemetry Row: Battery + Carrier Lock + Signal Strength
        el(
          'div',
          { class: 'radio-telemetry-row' },
          el(
            'div',
            { class: 'radio-battery-pill' },
            el('span', { class: 'pill-key' }, '⚡ BATT:'),
            this.#batteryValEl
          ),
          el(
            'div',
            { class: 'radio-lock-badge' },
            this.#lockLedEl,
            this.#lockLabelEl
          ),
          el(
            'div',
            { class: 'radio-smeter-pill' },
            el('span', { class: 'pill-key' }, 'SIGNAL:'),
            this.#signalPctEl
          )
        ),

        // VFD Frequency Display & Analog S-Meter
        (this.#vfdDisplayEl = el(
          'div',
          { class: 'radio-vfd-display' },
          el(
            'div',
            { class: 'vfd-digits-row' },
            this.#vfdFreqEl,
            el('span', { class: 'vfd-unit' }, 'MHz FM')
          ),
          this.#smeterBarEl
        )),

        // Analog Frequency Scale Marks (88 to 108 MHz)
        el(
          'div',
          { class: 'radio-dial-scale' },
          el('span', {}, '88'),
          el('span', {}, '92'),
          el('span', {}, '96'),
          el('span', {}, '100'),
          el('span', {}, '104'),
          el('span', {}, '108')
        ),

        // Tuning Control Dial & Steppers
        el(
          'div',
          { class: 'radio-tuning-controls' },
          el(
            'div',
            { class: 'tuning-steppers' },
            el(
              'button',
              {
                type: 'button',
                class: 'btn btn-ghost btn-sm',
                onclick: () => this.#tune(this.#sliderEl.value - 1.0),
              },
              '« -1.0'
            ),
            el(
              'button',
              {
                type: 'button',
                class: 'btn btn-ghost btn-sm',
                onclick: () => this.#tune(this.#sliderEl.value - FREQUENCY_STEP),
              },
              '‹ -0.1'
            )
          ),
          el(
            'div',
            { class: 'tuning-slider-wrapper' },
            this.#sliderEl
          ),
          el(
            'div',
            { class: 'tuning-steppers' },
            el(
              'button',
              {
                type: 'button',
                class: 'btn btn-ghost btn-sm',
                onclick: () => this.#tune(parseFloat(this.#sliderEl.value) + FREQUENCY_STEP),
              },
              '+0.1 ›'
            ),
            el(
              'button',
              {
                type: 'button',
                class: 'btn btn-ghost btn-sm',
                onclick: () => this.#tune(parseFloat(this.#sliderEl.value) + 1.0),
              },
              '+1.0 »'
            )
          )
        ),

        // Function Key Row: Auto-Scan, Dynamo Crank, Bookmark, SOS
        el(
          'div',
          { class: 'radio-function-row' },
          (this.#scanBtnEl = el(
            'button',
            {
              type: 'button',
              class: 'btn btn-ghost btn-sm btn-fkey',
              onclick: () => this.startAutoScan(),
            },
            '⚡ AUTO-SCAN'
          )),
          el(
            'button',
            {
              type: 'button',
              class: 'btn btn-ghost btn-sm btn-fkey',
              onclick: () => this.#engine.dispatch('radio/crank'),
            },
            '🔋 CRANK (+45m)'
          ),
          this.#bookmarkBtnEl,
          el(
            'button',
            {
              type: 'button',
              class: 'btn btn-ghost btn-sm btn-fkey btn-sos',
              onclick: () => {
                if (confirm(t('radio.ui.confirm_sos'))) {
                  this.#engine.dispatch('radio/broadcastSOS');
                }
              },
            },
            '🆘 BROADCAST SOS'
          )
        ),

        // Oscilloscope Screen
        el(
          'div',
          { class: 'radio-oscilloscope-box' },
          el('div', { class: 'oscilloscope-grid' }),
          this.#waveformEl,
          this.#oscStatusEl
        ),

        // Transcript / Decoded Teletype Box
        this.#transcriptContainerEl,

        // Bookmarks / Presets Chips
        el(
          'div',
          { class: 'radio-presets-row' },
          el('span', { class: 'presets-label' }, `${t('radio.ui.presets')}:`),
          (this.#presetsContainerEl = el(
            'div',
            { class: 'presets-chips' },
            ...RADIO_SIGNALS.map((sig) => {
              const isCurrent = Math.abs(sig.frequency - radioState.activeFrequency) < 0.08;
              return el(
                'button',
                {
                  type: 'button',
                  class: `preset-chip ${isCurrent ? 'is-active' : ''}`,
                  'data-freq': sig.frequency,
                  onclick: () => this.#tune(sig.frequency),
                },
                `📡 ${sig.frequency.toFixed(1)} MHz`
              );
            })
          ))
        )
      )
    );

    this.#rootEl.replaceChildren(card);
    this.#syncView(state);
  }

  /**
   * Smoothly synchronizes reactive telemetry values in-place without touching the slider DOM element!
   */
  #syncView(state) {
    if (!this.#isOpen || !this.#vfdFreqEl) return;

    const radioState = state.radio || RadioEngine.getInitialState();
    const reception = RadioEngine.getActiveReception(state);
    const { currentFreq, bestMatch, primaryQuality, isLocked, isPowered, batteryMinutes } = reception;

    // 1. Frequency VFD & Power
    if (this.#vfdDisplayEl) {
      this.#vfdDisplayEl.classList.toggle('is-power-off', !isPowered);
    }
    this.#vfdFreqEl.textContent = isPowered ? currentFreq.toFixed(1) : '---.-';

    if (this.#sliderEl) {
      this.#sliderEl.disabled = !isPowered;
      if (Math.abs(parseFloat(this.#sliderEl.value) - currentFreq) > 0.05) {
        this.#sliderEl.value = currentFreq;
      }
    }

    // 2. Power Button
    if (this.#powerBtnEl) {
      this.#powerBtnEl.className = `btn btn-xs ${isPowered ? 'btn-accent' : 'btn-ghost'}`;
      this.#powerBtnEl.textContent = isPowered ? `🟢 ${t('radio.ui.pwr_on')}` : `🔴 ${t('radio.ui.pwr_off')}`;
    }

    if (this.#scanBtnEl) {
      this.#scanBtnEl.disabled = !isPowered;
    }

    // 3. Battery
    if (this.#batteryValEl) {
      this.#batteryValEl.textContent = `${batteryMinutes}m`;
      this.#batteryValEl.className = batteryMinutes > 30 ? 'tone-good' : 'tone-bad';
    }

    // 4. S-Meter Segments
    if (this.#smeterBarEl) {
      const activeCount = isPowered ? Math.round(primaryQuality * 12) : 0;
      Array.from(this.#smeterBarEl.children).forEach((seg, idx) => {
        seg.className = `smeter-segment ${idx < activeCount ? 'is-active' : ''} ${idx >= 9 ? 'is-warn' : ''}`;
      });
    }

    // 5. Lock LED & Status
    if (this.#lockLedEl) {
      this.#lockLedEl.className = `lock-led ${isLocked && isPowered ? 'is-active' : ''}`;
    }
    if (this.#lockLabelEl) {
      this.#lockLabelEl.textContent = !isPowered
        ? t('radio.ui.pwr_off')
        : isLocked
          ? t('radio.ui.carrier_lock')
          : t('radio.ui.scanning_carrier');
    }
    if (this.#signalPctEl) {
      this.#signalPctEl.textContent = isPowered ? `${Math.round(primaryQuality * 100)}%` : '0%';
    }

    // Audio cue on lock acquisition
    if (isLocked && !this.#wasLocked && isPowered && !this.#scanTimer) {
      try {
        audioEngine.playRadioMorseChirp();
      } catch (_) {}
    }
    this.#wasLocked = Boolean(isLocked && isPowered);

    // 6. Bookmark button state
    if (this.#bookmarkBtnEl) {
      const isBookmarked = radioState.bookmarks?.includes(currentFreq);
      this.#bookmarkBtnEl.textContent = isBookmarked ? '★ SAVED' : '☆ SAVE';
      this.#bookmarkBtnEl.classList.toggle('is-bookmarked', Boolean(isBookmarked));
      this.#bookmarkBtnEl.disabled = !isPowered;
    }

    // 7. Oscilloscope
    if (this.#waveformEl) {
      this.#waveformEl.className = `oscilloscope-waveform ${!isPowered ? 'is-off' : isLocked ? 'is-locked-wave' : 'is-noise-wave'}`;
    }
    if (this.#oscStatusEl) {
      if (!this.#scanTimer) {
        this.#oscStatusEl.textContent = !isPowered
          ? 'TRANSCEIVER STANDBY // DC POWER OFF'
          : isLocked
            ? `AUDIO DEMODULATOR: LOCKED ONTO [${t(bestMatch.signal.nameKey)}]`
            : 'AUDIO DEMODULATOR: CARRIER NOISE / SQUELCH ACTIVE';
      }
    }

    // 8. Preset Chips Active State
    if (this.#presetsContainerEl) {
      Array.from(this.#presetsContainerEl.children).forEach((chip) => {
        const chipFreq = parseFloat(chip.dataset.freq);
        chip.classList.toggle('is-active', Math.abs(chipFreq - currentFreq) < 0.08);
      });
    }

    // 9. Transcript box content
    if (this.#transcriptContainerEl) {
      this.#renderTranscript(this.#transcriptContainerEl, reception);
    }
  }

  #renderTranscript(container, reception) {
    const { bestMatch, primaryQuality, isPowered } = reception;

    if (!isPowered) {
      container.replaceChildren(
        el(
          'div',
          { class: 'transcript-empty-state tone-warn' },
          `⚡ ${t('radio.ui.no_power_msg')}`
        )
      );
      return;
    }

    if (!bestMatch || primaryQuality < 0.15) {
      container.replaceChildren(
        el(
          'div',
          { class: 'transcript-empty-state' },
          el('div', { class: 'static-text' }, '· · · [STATIC HISS // NO CARRIER DETECTED] · · ·'),
          el('p', { class: 'muted-note' }, t('radio.ui.tuning_hint'))
        )
      );
      return;
    }

    const { signal, isDecoded, quality, distanceKm } = bestMatch;

    const transcriptCard = el(
      'div',
      { class: 'transcript-active-card' },
      el(
        'div',
        { class: 'transcript-header' },
        el('strong', { class: 'transcript-caller' }, t(signal.callerKey)),
        el('span', { class: 'transcript-distance' }, `~${distanceKm} km`),
        el('span', { class: `badge ${signal.type}` }, signal.type.toUpperCase())
      ),
      el('h4', { class: 'transcript-title' }, t(signal.nameKey)),
      el(
        'div',
        { class: 'transcript-body' },
        quality >= 0.65
          ? t(signal.transcriptKey)
          : this.#garbleTranscript(t(signal.transcriptKey), quality)
      ),
      el(
        'div',
        { class: 'transcript-actions' },
        isDecoded
          ? el('span', { class: 'decoded-pill tone-good' }, `✔ ${t('radio.ui.decoded_plotted')}`)
          : el(
              'button',
              {
                type: 'button',
                class: 'btn btn-accent btn-sm',
                onclick: () => this.#engine.dispatch('radio/decode', { signalId: signal.id }),
              },
              `🛰️ ${t('radio.ui.decode_and_plot')}`
            )
      )
    );

    container.replaceChildren(transcriptCard);
  }

  #garbleTranscript(fullText, quality) {
    return fullText
      .split(' ')
      .map((word) => (Math.random() > quality ? '···' : word))
      .join(' ');
  }
}


